parameters.jsCode:
// Talents (ALLY 24, BA5, Stefan 19.10.2026): Überblick, Alle Talents (Tabelle, sortierbar, 20 je Seite), Einladungen, Zahlen aus Screenshots, Archiv.
// Daten wie ALLY 8: talents_web_daten, talents_uebersicht, talents_kachel, talents_warnzeichen, Zahlen der letzten 28 Tage (talents_kanal_zahlen).
// Formulare mit den Aktionsnamen und Feldern von ALLY 8 (tl_*, ti_*), Felder = Schlüssel der Datenbank-Aktion. Liefert nur die Seitenbeschreibung (JSON).
// Migration 65 (Stefan 20.10.2026, 09:23/09:26): Filter „Manuelle Daten“ im Kopf (einbeziehen/nicht einbeziehen), Zahlen mit manuellen Daten ohne Doppelzählung,
// „Doppelte Daten prüfen“ als offener Punkt je Talent (Ziel: Talent-Seite, Abschnitt Doppelte Daten), i-Symbol mit der Info zu Zahlen per Screenshot.
// Punkt 5e (Stefan 21.10.2026): wie die Rangliste in ALLY 8 – Zeitraum wählbar (Kopf, mit Von/Bis bei „Eigener Zeitraum“), Platz (unter Reichweite), Spalten Interaktionen, Veränderung
// (Pfeil und Farbe) und Follower-Zuwachs (unter Follower), Warnhinweis am Talent (erste Warnung + Anzahl weiterer, „Zahlen prüfen (n)“, „Noch keine Zahlen“), Zeitraum- und
// Vergleichszeile mit Datenstand, Hinweise zu den Zahlen als i-Symbol am Abschnitt. Accounts stehen wie in ALLY 8 unter dem Namen.
// BA10 (Migration 69): Abschnitt „Wochen-Briefing“ (Kachel seit Stefan 24.10.2026, 20:20/20:26 „Briefings“; Briefing-Titel, Fenster und Einstellung unverändert bis K5) – die letzten Wochen-Briefings der Person zum Lesen (Seitenfenster, er=<id>) und „Jetzt erstellen“
// (Aktion wochen_briefing_jetzt, ALLY 20 startet TALENTS Wochen-Briefing). Nur sichtbar, wenn die Person ein Wochen-Briefing bekommt oder schon eines hat.
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const titel = String(F.name || 'Dashboard');
const kopf = { schluessel: 'talents', art: 'funktion', titel, beschreibung: String(F.beschreibung || ''), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
if (/^[a-z0-9-]{1,40}$/.test(String(F.einstellungen_ziel || ''))) kopf.zahnrad = { ziel: { seite: 'einstellungen', parameter: { bereich: String(F.einstellungen_ziel) } } };
const W = D.d || {};
if (W.ok !== true) {
  return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn', text: String(W.fehler || 'Die Talents konnten nicht geladen werden. Bitte die Seite neu laden.') }] } } }];
}
const verw = W.darf_verwalten === true, adm = W.darf_loeschen === true;
// BA6 (Stefan 20.10.2026): Management lädt eigene Talents selbst ein (automatisch zuständig, talents_ui_rechte); Import und Zuständig-Auswahl bleiben bei „Talents verwalten“
const anlegen = verw || (D.r && D.r.anlegen === true);
const Z = D.zahlen || {}, ZO = D.zahlen_offen || {}, ZU = D.zustand || {};
const MZ = String(D.manuell || '1') !== '0';
const IM = Array.isArray(D.info_manuell) ? D.info_manuell.map(String) : [];
// Punkt 5e: Zeitraum wie ALLY 8 (Auswahl aus talents_zeitraeume, bei „Eigener Zeitraum“ zusätzlich Von und Bis)
const ZR = D.zr && typeof D.zr === 'object' ? D.zr : {};
const ZRL = Array.isArray(D.zeitraeume) ? D.zeitraeume.filter(z => z && /^[a-z0-9]{1,20}$/.test(String(z.schluessel || ''))) : [];
const zrFelder = ZRL.length ? [{ typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum', ausklappliste: true, wert: String(ZR.schluessel || '28tage'), optionen: ZRL.map(z => ({ wert: String(z.schluessel), text: String(z.name || z.schluessel) })) }] : [];
if (ZR.schluessel === 'frei') zrFelder.push({ typ: 'datum', name: 'von', label: 'Von', wert: String(ZR.frei_von || ZR.von || '') }, { typ: 'datum', name: 'bis', label: 'Bis', wert: String(ZR.frei_bis || ZR.bis || '') });
const ZRKURZ = { '7tage': '7 Tage', '28tage': '28 Tage', monat: 'dieser Monat', vormonat: 'Vormonat', frei: 'im Zeitraum' };
const zrKurz = ZRKURZ[ZR.schluessel] || '28 Tage';
// Stefan 24.10.2026, 15:00 (A1/A2): Zeitraum als Ausklappliste, „Manuelle Daten einbeziehen“ als Häkchen (angehakt = einbeziehen, sonst manuell=0); das i bleibt
kopf.filter = { id: 'manuell', label: 'Zahlen filtern', felder: zrFelder.concat([{ typ: 'haken', name: 'manuell', label: 'Manuelle Daten einbeziehen', wert: MZ ? '1' : '0', wert_an: '1', wert_aus: '0',
  info: 'Manuelle Daten sind Zahlen aus einem manuellen Import von Insights, die geprüft und bestätigt wurden. Ist die Option deaktiviert, werden ausschließlich automatisch geladene Zahlen berücksichtigt.' }]) };
const alle = Array.isArray(W.talents) ? W.talents : [];
const aktive = alle.filter(t => t.status === 'aktiv'), archiv = alle.filter(t => t.status === 'archiviert');
const name = t => String(t.anzeigename || t.name || ('Talent ' + t.id));
const profil = t => ({ seite: 'talent', parameter: { id: t.id } });
const kanaele = t => (Array.isArray(t.kanaele) ? t.kanaele : []).filter(k => k.status !== 'getrennt');
const warnungen = t => ((Z[String(t.id)] || {}).warnungen || []);
const ernst = t => warnungen(t).filter(w => w.stufe === 'warnung');
const zahl = n => Number(n).toLocaleString('de-DE');
// C (Stefan 24.10.2026, 15:00/15:33): Auswahl „Talent“ unter Zeitraum und Häkchen; mit gewähltem Talent stehen darunter dessen Details wie auf dem Profil
// (die Oberfläche holt sie wie die Profilseite von ALLY 25, ohne deren Kopf), daneben „Talent-Profil“. Gesamt-Kennzahlen und Kacheln entfallen dann, die Liste bleibt.
const tw = aktive.some(t => String(t.id) === String(P.talent || '')) ? String(P.talent) : '';
// Stefan 29.10.2026, 08:16: „Talent“ steht vor „Zeitraum“ (Häkchen „Manuelle Daten einbeziehen“ bleibt am Ende der Reihe)
kopf.filter.felder.unshift(Object.assign({ typ: 'auswahl', name: 'talent', label: 'Talent', ausklappliste: true, loeschbar: true, wert: tw,
  optionen: [{ wert: '', text: 'Talent wählen' }].concat(aktive.slice().sort((a, b) => name(a).localeCompare(name(b), 'de') || a.id - b.id).map(t => ({ wert: String(t.id), text: name(t) }))) },
  tw ? { knopf: { text: 'Talent-Profil', ziel: { seite: 'talent', parameter: { id: tw } } } } : {}));
if (tw) kopf.einbettung = { seite: 'talent', parameter: { id: tw }, ohne_parameter: ['talent'], ohne_filter: ['zeitraum', 'von', 'bis', 'manuell'] };

// ---------- Überblick ----------
const sm = ((D.u || {}).summe) || {};
let kanAlle = 0, kanVerb = 0;
for (const t of aktive) for (const k of kanaele(t)) { kanAlle++; if (k.status === 'verbunden') kanVerb++; }
const DO = t => Number((Z[String(t.id)] || {}).doppelt_offen) || 0;
// Fehlerbehebung (Koordinator 30.10.2026): abgelaufene Einladung zählt nur, wenn talents_talent_stand einladung_abgelaufen bzw. link_noetig meldet oder kein Kanal
// verbunden ist (Spalte stand aus „Daten laden“). Entfällt nur, wenn mindestens ein Kanal verbunden ist und der Stand nichts meldet.
const SD = D.stand && typeof D.stand === 'object' ? D.stand : {};
const einlAbg = t => !!(t.einladung && t.einladung.abgelaufen === true) && (s => s.einladung_abgelaufen === true || s.link_noetig === true || s.verbunden !== true)(SD[String(t.id)] || {});
const aufmerksam = aktive.filter(t => ernst(t).length || ZO[String(t.id)] || DO(t));  // wie „Offen“: ohne abgelaufene Einladungen (Stefan/Koordinator 30.10.2026)
const rw = sm.reichweite || {}, ve = (rw.veraenderung || {});
const kennzahlen = [
  { label: 'Aktive Talents', wert: zahl(aktive.length), neben: archiv.length ? archiv.length + ' im Archiv' : '' },
  { label: 'Verbundene Accounts', wert: kanVerb + ' / ' + kanAlle, neben: kanAlle - kanVerb ? (kanAlle - kanVerb) + ' offen' : 'alle verbunden', ton: kanAlle - kanVerb ? 'warn' : '' },
  { label: 'Reichweite ' + zrKurz, wert: String(rw.text || '–'), neben: ve.prozent !== null && ve.prozent !== undefined ? String(ve.text || '') + ' zum Vorzeitraum'
      : (!MZ ? 'ohne manuelle Daten' : Number(sm.manuell) > 0 ? 'inkl. manueller Daten' : ''), ton: ve.prozent !== null && ve.prozent !== undefined ? (ve.richtung === 'runter' ? 'warn' : ve.richtung === 'hoch' ? 'ok' : '') : '' },
  { label: 'Brauchen Aufmerksamkeit', wert: zahl(aufmerksam.length), neben: aufmerksam.length ? 'siehe „Offen“' : '', ton: aufmerksam.length ? 'warn' : '', ziel: { seite: 'talents', parameter: { status: 'aufmerksamkeit' }, anker: 'a-alle' } }
];
const MARKE = { abgelaufen: 'abgelaufen', laeuft_ab: 'läuft ab', einbruch: 'Einbruch', abruf_fehler: 'Fehler' };
const offen = [];
for (const t of aktive) {
  for (const w of ernst(t)) offen.push({ marke: { text: MARKE[w.art] || 'prüfen', ton: 'warn' }, text: name(t) + ': ' + String(w.text || ''), ziel: profil(t), ziel_text: 'Ansehen' });
  // 7f (Koordinator 25.10.2026, analog Stefans 7e „Direkt zum Prüfen“): in den Datenimport des Talents › „Zur Prüfung“ statt ins Profil › Daten und Notizen
  if (ZO[String(t.id)]) offen.push({ marke: { text: 'prüfen' }, text: name(t) + ': ' + ZO[String(t.id)] + (ZO[String(t.id)] === 1 ? ' manuellen Wert prüfen' : ' manuelle Werte prüfen'),
    ziel: { seite: 'talent', parameter: { id: t.id, w: 'zahlen' }, anker: 'a-pruefung' }, ziel_text: 'Prüfen' });
  // Migration 65: doppelte Daten (manuell und automatisch) – die zuständige Person entscheidet auf der Talent-Seite
  if (DO(t)) offen.push({ marke: { text: 'doppelt', ton: 'warn' }, text: name(t) + ': ' + DO(t) + (DO(t) === 1 ? ' doppelten Wert prüfen' : ' doppelte Werte prüfen'),
    ziel: { seite: 'talent', parameter: { id: t.id }, anker: 'a-doppelte-daten' }, ziel_text: 'Prüfen' });
  // Stefan 30.10.2026: abgelaufene Einladungen stehen nur in der Kachel „Einladungen“ (mit „Neuer Link“), nicht mehr in „Offen“
}
for (const t of archiv) if (t.loeschen_am) offen.push({ marke: { text: 'Löschung', ton: 'warn' }, text: name(t) + ': wird frühestens am ' + t.loeschen_am + ' gelöscht', ziel: { seite: 'talents', anker: 'a-archiv' }, ziel_text: 'Archiv' });
const meldungen = [];
const K = D.k || {};
if (K.neue_beitraege && K.neue_beitraege.text) meldungen.push({ text: String(K.neue_beitraege.text) });
const vor7 = Date.now() - 7 * 864e5;
const datum = s => { const m = /^(\d{2})\.(\d{2})\.(\d{4})/.exec(String(s || '')); return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) : 0; };
for (const t of aktive) for (const k of kanaele(t)) if (k.status === 'verbunden' && datum(k.verbunden_am) >= vor7)
  meldungen.push({ text: name(t) + ' hat ' + String(k.name || k.plattform || '') + ' verbunden', neben: String(k.verbunden_am || '') }); // Meldungen nur zur Information, ohne Ziel (Stefan 24.10.2026, 20:43)
const ueberblick = { kennzahlen, karten: [
  // „Alle anzeigen“ (Stefan 21.10.2026, 14:18/14:19): alle Einträge; der Baukasten zeigt im Überblick 5 und auf der eigenen Seite alle (blättert ab 20)
  { titel: 'Offen', leer: 'Nichts offen.', eintraege: offen },
  { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: meldungen }] };

// ---------- Alle Talents ----------
const plattformen = Array.isArray(W.plattformen) ? W.plattformen : [];
const personen = (Array.isArray(W.personen) ? W.personen : []);
const q = String(P.q || '').trim().toLowerCase().slice(0, 100);
const pf = plattformen.some(p => p.schluessel === P.plattform) ? P.plattform : '';
const zs = verw && personen.some(p => p.id === P.zustaendig) ? P.zustaendig : '';
const st = ['aufmerksamkeit', 'eingeladen', 'verbunden'].includes(P.status) ? P.status : '';
const zustand = t => {
  const e = ernst(t)[0];
  if (e) return { text: MARKE[e.art] || 'prüfen', ton: 'warn', rang: 0 };
  const ks = kanaele(t);
  if (!ks.some(k => k.status === 'verbunden') && t.einladung && (t.einladung.abgelaufen !== true || einlAbg(t))) return { text: t.einladung.abgelaufen ? 'Einladung abgelaufen' : 'eingeladen', ton: t.einladung.abgelaufen ? 'warn' : 'grau', rang: 1 };
  if (ks.some(k => k.status !== 'verbunden')) return { text: 'teilweise verbunden', ton: 'grau', rang: 2 };
  return { text: 'in Ordnung', ton: 'ok', rang: 3 };
};
// Aufbau-Auftrag Punkt 3 (Stefan 24.10.2026): ein Suchfeld statt Ausklapplisten – die Suche findet zusätzlich Plattform, Zuständig und Status (wie die Spalten zeigen);
// mehrere Wörter müssen alle vorkommen. Rein lesend; die bisherige Suche (Name, Künstlername, Mail, @Account) trifft wie bisher.
const plName = k => { const p = plattformen.find(x => x.schluessel === k.plattform); return String((p && p.name) || k.plattform || ''); };
const sucheText = t => (name(t) + ' ' + (t.name || '') + ' ' + (t.kuenstlername || '') + ' ' + (t.email || '') + ' ' + kanaele(t).map(k => k.extern_name || '').join(' ')).toLowerCase();
const sucheMehr = t => { const vb = kanaele(t).some(k => k.status === 'verbunden');
  return [sucheText(t), kanaele(t).map(k => plName(k) + ' ' + String(k.name || '')).join(' '), (t.zustaendig || []).map(p => String(p.name || '')).join(' '), zustand(t).text,
    aufmerksam.includes(t) ? 'braucht aufmerksamkeit' : '', t.einladung && !vb ? 'eingeladen' : '', vb ? 'verbunden' : ''].join(' ').toLowerCase(); };
// D (Migration 147): dieselbe Suche für „Meine Talents“ (eigener Parameter mq)
const trifftQ = (t, q) => { const qWorte = q.split(/\s+/).map(x => x.replace(/^@/, '')).filter(Boolean);
  return sucheText(t).includes(q.replace(/^@/, '')) || (qWorte.length > 0 && (h => qWorte.every(x => h.includes(x)))(sucheMehr(t))); };
const trifft = t => trifftQ(t, q);
let zeilen = aktive.filter(t => {
  if (q && !trifft(t)) return false;
  if (pf && !kanaele(t).some(k => k.plattform === pf)) return false;
  if (zs && !(t.zustaendig || []).some(p => p.id === zs)) return false;
  if (st === 'aufmerksamkeit' && !aufmerksam.includes(t)) return false;
  if (st === 'eingeladen' && !(t.einladung && !kanaele(t).some(k => k.status === 'verbunden'))) return false;
  if (st === 'verbunden' && !kanaele(t).some(k => k.status === 'verbunden')) return false;
  return true;
});
// Hinweise zu den Zahlen (ALLY 8 unter der Rangliste): Erklärung Platz und Veränderung, Plattform-Hinweise, von Ally berechnete Werte, Verzögerung der Zahlen –
// als i-Symbol am Abschnitt „Alle Talents“ (an den Spalten würde die Tabelle zu breit)
const HW = ['Platz (unter Reichweite): Rang nach Reichweite im gewählten Zeitraum. Veränderung: Reichweite gegenüber dem Vorzeitraum. Unter Follower steht der Zuwachs im Zeitraum.'].concat(Array.isArray((D.u || {}).hinweise) ? D.u.hinweise : [], (D.u || {}).abgeleitet === true && D.u.abgeleitet_text ? ['* ' + D.u.abgeleitet_text] : [],
  (D.u || {}).hinweis_verzoegerung ? [D.u.hinweis_verzoegerung] : []).filter(x => typeof x === 'string' && x).map(String);
// D (Migration 147, Stefan 24.10.2026): eine Tabelle je Liste („Meine Talents“, „Alle Talents“) – Spalten, Sortierung (Zustand talents.<liste>), Platz
// (unter den Talents dieser Liste) und Blättern (?p=<liste>:n) wie bisher bei „Alle Talents“
const tabelleFuer = (tid, titel, zeilen, leer, extra) => {
  const SP = ['name', 'follower', 'reichweite', 'interaktionen', 'veraenderung', 'zustaendig', 'status'];
  // Platz wie in ALLY 8 (hier unter der Reichweite, damit die Tabelle nicht zu breit wird): Rang nach Reichweite im Zeitraum unter den gefilterten Talents, bei gleichem Wert nach Name; Talents ohne Zahlen bekommen keinen Platz („–“)
  const rwWert = t => { const w = ((Z[String(t.id)] || {}).reichweite || {}).wert; return w === null || w === undefined || !isFinite(Number(w)) ? null : Number(w); };
  const PLATZ = new Map(zeilen.filter(t => rwWert(t) !== null).sort((a, b) => rwWert(b) - rwWert(a) || name(a).localeCompare(name(b), 'de') || a.id - b.id).map((t, i) => [t.id, i + 1]));
  const kz = (t, k) => (Z[String(t.id)] || {})[k] || {};
  const zahlOder = v => v === null || v === undefined || !isFinite(Number(v)) ? null : Number(v);
  const so0 = (ZU['talents.' + tid] || {}).sortierung || {};
  const so = { spalte: SP.includes(so0.spalte) ? so0.spalte : 'name', richtung: so0.richtung === 'ab' ? 'ab' : 'auf' };
  const accounts = t => kanaele(t).map(k => String(k.name || k.plattform || '')).filter((x, i, a) => x && a.indexOf(x) === i).join(', ');
  const zustaendig = t => (t.zustaendig || []).map(p => String(p.name || '')).join(', ');
  const wertVon = (t, sp) => sp === 'name' ? name(t).toLowerCase() : sp === 'zustaendig' ? zustaendig(t).toLowerCase() : sp === 'platz' ? (PLATZ.has(t.id) ? PLATZ.get(t.id) : null)
    : sp === 'status' ? zustand(t).rang : sp === 'follower' ? zahlOder(kz(t, 'follower').wert) : sp === 'interaktionen' ? zahlOder(kz(t, 'interaktionen').wert)
    : sp === 'veraenderung' ? zahlOder((kz(t, 'reichweite').veraenderung || {}).prozent) : zahlOder(kz(t, 'reichweite').wert);
  // Warnhinweis am Talent wie ALLY 8 (Migration 51): „Zahlen prüfen (n)“, erste Warnung (+ Anzahl weiterer), „Noch keine Zahlen“. Nur Warnungen der Stufe „warnung“
  // stehen mit Text in der Zeile; reine Hinweise (z. B. „Keine neuen Zahlen seit …“) stehen auf der Talent-Seite, sonst wird die Tabelle unübersichtlich hoch.
  const warnText = t => { const W = ernst(t), n = Number(ZO[String(t.id)]) || 0;
    return [n > 0 ? 'Zahlen prüfen (' + n + ')' : '', W.length ? String(W[0].text || '') + (W.length > 1 ? ' (+' + (W.length - 1) + ')' : '') : '',
      (Z[String(t.id)] || {}).hat_daten === false ? 'Noch keine Zahlen' : ''].filter(Boolean).join(' · '); };
  const trendZelle = v => v && v.text && v.text !== '–' ? { trend: { text: String(v.text), richtung: ['hoch', 'runter'].includes(v.richtung) ? v.richtung : 'gleich' } } : '–';
  zeilen.sort((a, b) => {
    const x = wertVon(a, so.spalte), y = wertVon(b, so.spalte);
    if (x === null && y !== null) return 1; if (y === null && x !== null) return -1;
    let c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? ''), 'de');
    if (so.richtung === 'ab') c = -c;
    return c || name(a).localeCompare(name(b), 'de') || a.id - b.id;
  });
  const JE = 20, gesamt = zeilen.length, seiten = Math.max(1, Math.ceil(gesamt / JE));
  const seite = Math.min(seiten, Math.max(1, Number((E.seiten || {})[tid]) || 1));
  return Object.assign({ typ: 'tabelle', id: tid, titel,
    spalten: [{ schluessel: 'name', titel: 'Talent', sortierbar: true }, { schluessel: 'follower', titel: 'Follower', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'reichweite', titel: 'Reichweite', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'interaktionen', titel: 'Interaktionen', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'veraenderung', titel: 'Veränderung', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'zustaendig', titel: 'Manager/in', sortierbar: true }, { schluessel: 'status', titel: 'Status', sortierbar: true }],
    zeilen: zeilen.slice((seite - 1) * JE, seite * JE).map(t => { const z = Z[String(t.id)] || {}, s = zustand(t), fz = z.follower_zuwachs || {}, wt = warnText(t);
      return { id: t.id, zellen: { name: Object.assign({ text: name(t), ziel: profil(t) }, accounts(t) ? { neben: accounts(t) } : {}), 
        follower: Object.assign({ text: String((z.follower || {}).text || '–') }, fz.wert !== null && fz.wert !== undefined && fz.text && fz.text !== '–' ? { neben: String(fz.text) } : {}),
        reichweite: Object.assign({ text: String((z.reichweite || {}).text || '–') }, PLATZ.has(t.id) ? { neben: 'Platz ' + PLATZ.get(t.id) } : {}), interaktionen: String((z.interaktionen || {}).text || '–'), veraenderung: trendZelle((z.reichweite || {}).veraenderung),
        zustaendig: zustaendig(t) || '–', status: Object.assign({ marke: { text: s.text, ton: s.ton } }, wt ? { neben: wt } : {}, s.ton === 'warn' || Number(ZO[String(t.id)]) > 0 ? { ton: 'warn' } : {}) } }; }),
    // E10 (Stefan 23.10.2026, 16:07; Koordinator 24.10.2026): „Alle markieren“ = alle Einträge mit dem aktuellen Filter, auch auf den anderen Seiten – die Nummern liefert der Server
    alle_ids: zeilen.map(t => t.id),
    sortierung: so, seite, je_seite: JE, gesamt, leer }, extra || {});
};
const leerAlle = aktive.length ? 'Keine Talents für diesen Filter.' : (verw ? 'Noch keine Talents.' : 'Dir sind noch keine Talents zugeordnet.');
// D (Stefan 24.10.2026, 16:58/17:00): markierte Zeilen – „Zu meiner Liste“ bzw. „Von Liste entfernen“ steht direkt an der Liste (nicht im Kopf-Menü), ohne Rückfrage
const tabelle = tabelleFuer('alle', 'Alle Talents', zeilen, leerAlle, { auswahl_aktionen: [{ text: 'Zu meiner Liste', aktion: 'tl_liste_hinzu' }] });
const ML = new Set((Array.isArray(D.meine_liste) ? D.meine_liste : []).map(String));
const mq = String(P.mq || '').trim().toLowerCase().slice(0, 100);
const meineAlle = aktive.filter(t => ML.has(String(t.id)));
const tabMeine = tabelleFuer('meine', 'Meine Talents', meineAlle.filter(t => !mq || trifftQ(t, mq)),
  !aktive.length ? leerAlle : meineAlle.length ? 'Keine Talents für diese Suche.' : 'Deine Liste ist leer. Markiere Talents unter „Alle Talents“ und wähle „Zu meiner Liste“.',
  { auswahl_aktionen: [{ text: 'Von Liste entfernen', aktion: 'tl_liste_entfernen' }] });
const filterFelder = [{ typ: 'suche', name: 'q', label: 'Suche', platzhalter: 'Name oder @Account', wert: String(P.q || '').slice(0, 100) },
  { typ: 'auswahl', name: 'plattform', label: 'Plattform', wert: pf, optionen: [{ wert: '', text: 'Alle' }].concat(plattformen.map(p => ({ wert: p.schluessel, text: String(p.name || p.schluessel) }))) }];
if (verw) filterFelder.push({ typ: 'auswahl', name: 'zustaendig', label: 'Manager/in', wert: zs, optionen: [{ wert: '', text: 'Alle' }].concat(personen.filter(p => p.hat_recht).map(p => ({ wert: p.id, text: String(p.name || '') }))) });
filterFelder.push({ typ: 'auswahl', name: 'status', label: 'Status', wert: st, optionen: [{ wert: '', text: 'Alle' }, { wert: 'aufmerksamkeit', text: 'Braucht Aufmerksamkeit' },
  { wert: 'eingeladen', text: 'Eingeladen' }, { wert: 'verbunden', text: 'Verbunden' }] });
// Punkt 5e: Zeitraum, Vergleich und Datenstand als graue Zeile über der Tabelle (wie ALLY 8), Fehler oder Hinweis zum Zeitraum als Text
const UD = (D.u && typeof D.u === 'object') ? D.u : {};
const zrZeile = [ZR.text, ZR.vor_text, (UD.datenstand || {}).text].filter(Boolean).map(String).join(' · ');
const zrInhalt = [ZR.fehler ? { typ: 'text', ton: 'warn', text: String(ZR.fehler) } : null, ZR.hinweis ? { typ: 'text', ton: 'grau', text: String(ZR.hinweis) } : null,
  zrZeile ? { typ: 'text', ton: 'grau', text: zrZeile } : null].filter(Boolean);
// D (Stefan 24.10.2026, 16:58/17:00): oben „Meine Talents“ (offen), darunter „Alle Talents“ (zu; offen, solange die eigene Liste leer ist)
const abschnitte = [{ id: 'meine', titel: 'Meine Talents', zahl: String(tabMeine.gesamt), offen_standard: true, info: HW, inhalt: [{ typ: 'filter', id: 'meine', label: 'Meine Talents durchsuchen',
    felder: [{ typ: 'suche', name: 'mq', label: 'Suche', platzhalter: 'Name oder @Account', wert: String(P.mq || '').slice(0, 100) }] }].concat(zrInhalt, [tabMeine]) },
  { id: 'alle', titel: 'Alle Talents', zahl: String(tabelle.gesamt), offen_standard: !meineAlle.length, info: HW, inhalt: [{ typ: 'filter', id: 'alle', label: 'Talents filtern', felder: filterFelder }].concat(zrInhalt, [tabelle]) }];

// ---------- Einladungen ----------
const eingeladen = aktive.filter(t => t.einladung && ((kanaele(t).some(k => k.status !== 'verbunden') && (t.einladung.abgelaufen !== true || einlAbg(t))) || einlAbg(t)));  // Fehlerbehebung 30.10.2026; Stefan 30.10.: jede abgelaufene (einlAbg) hier
// „Alle anzeigen“ (Stefan 21.10.2026): Einladungen und Archiv blättern je 20 (Seite aus ?p=einladungen:n bzw. archiv:n), statt nach 20 abzuschneiden
const blattVon = (tab, n) => Math.min(Math.max(1, Math.ceil(n / 20)), Math.max(1, Number((E.seiten || {})[tab]) || 1));
const eiSeite = blattVon('einladungen', eingeladen.length), eiTeil = eingeladen.slice((eiSeite - 1) * 20, eiSeite * 20);
abschnitte.push({ id: 'einladungen', titel: 'Einladungen', zahl: eingeladen.length + ' offen', offen_standard: false, inhalt: [{ typ: 'tabelle', id: 'einladungen', titel: 'Einladungen',
  spalten: [{ schluessel: 'name', titel: 'Talent' }, { schluessel: 'offen', titel: 'Noch nicht verbunden' }, { schluessel: 'bis', titel: 'Gültig bis' }, { schluessel: 'link', titel: 'Link' }],
  zeilen: eiTeil.map(t => ({ zellen: { name: { text: name(t), ziel: profil(t) },
    offen: kanaele(t).filter(k => k.status !== 'verbunden').map(k => String(k.name || k.plattform || '')).join(', '),
    bis: t.einladung.abgelaufen ? { marke: { text: 'abgelaufen', ton: 'warn' }, text: String(t.einladung.gueltig_bis || '') } : String(t.einladung.gueltig_bis || ''),
    link: Object.assign({ text: t.einladung.link ? String(t.einladung.link) : '' }, verw ? { aktion: { text: 'Neuer Link', aktion: 'tl_einladung_neu', werte: { id: t.id } } } : {}) } })),
  sortierung: {}, seite: eiSeite, je_seite: 20, gesamt: eingeladen.length, leer: 'Keine offenen Einladungen.' }]
  // E2 (Stefan 24.10.2026, 16:03): bisher im Aktionen-Menü, Aktion und Rückfrage unverändert; nur mit offenen Einladungen in der Kachel (sonst fällt sie weg, der Knopf steht im Menü)
  .concat(verw && eingeladen.length ? [{ typ: 'aktion', text: 'Neue Links erstellen', aktion: 'tl_links_erneuern', frage: 'Für alle abgelaufenen Verbindungen und Einladungen neue Links erstellen?' }] : []) });

// ---------- Manuelle Daten prüfen (bis 24.10.2026 „Zahlen aus Screenshots“, Stefan 15:00 A3; Zahl = Werte, nicht Vorschläge) ----------
const zo = aktive.filter(t => ZO[String(t.id)]);
abschnitte.push({ id: 'screenshots', titel: 'Manuelle Daten prüfen', zahl: zo.length ? zo.reduce((s, t) => s + ZO[String(t.id)], 0) + ' zu prüfen' : '0', offen_standard: false, info: IM.length ? IM : undefined,
  inhalt: [{ typ: 'liste', leer: 'Keine Werte zu prüfen.', eintraege: zo.map(t => ({ fett: name(t), text: ZO[String(t.id)] + (ZO[String(t.id)] === 1 ? ' Wert' : ' Werte') + ' zu bestätigen',
    // 7e (Stefan 25.10.2026: „Direkt zum Prüfen“): in den Datenimport des Talents › „Zur Prüfung“ statt ins Profil › Daten und Notizen
    ziel: { seite: 'talent', parameter: { id: t.id, w: 'zahlen' }, anker: 'a-pruefung' }, ziel_text: 'Prüfen' })) }] });

// ---------- BA10: Wochen-Briefing ----------
const fensterWb = [];
const WB = D.wb && D.wb.ok === true && Array.isArray(D.wb.liste) ? D.wb.liste.filter(x => /^[0-9]{1,9}$/.test(String(x.id))) : [];
const wbEmpf = D.wb_empf === true;
if (wbEmpf || WB.length || (D.wb && D.wb.seite === true)) {
  const erWahl = /^[0-9]{1,12}$/.test(String(P.er || '')) ? String(P.er) : '';
  const hierWb = extra => ({ seite: 'talents', parameter: Object.assign({}, extra || {}), anker: 'a-wochen-briefing' });
  // Migration 180 (KI-Analyse, Koordinator 30.10.2026): die letzten fünf Ergebnisse der Person; „Lesen“ öffnet das Ergebnis mit Kopf und vollem Text auf der Seite
  // KI-Analysen. Erstellt wird dort (Einstellungen zuerst, Ergebnis sofort sichtbar), deshalb hier kein „Jetzt erstellen“ mehr.
  // Migration 208 (eine Funktion „Briefing“, Stefan 06.11.2026): Kachel „Briefings“ – Briefings der Person mit Inhalten des Social-Media-Pakets, je mit Zeitplan und letztem Ergebnis; Link zur Seite Briefing
  const inhaltWb = [{ typ: 'liste', leer: 'Noch keine Briefings mit Zahlen der Talents.',
    eintraege: WB.map(x => ({ fett: String(x.name || 'Briefing'), neben: [String(x.zeitplan || ''), x.letzter ? 'zuletzt ' + String(x.letzter) : ''].filter(Boolean).join(' · '), ziel_text: 'Öffnen',
      ziel: { seite: 'morgen-briefing', parameter: Object.assign({ briefing: String(x.id) }, /^[0-9]{1,12}$/.test(String(x.ergebnis_id || '')) ? { ergebnis: String(x.ergebnis_id) } : {}) } })) }];
  // Stefan 24.10.2026, 20:59: Link „Alle Briefings“ zur künftigen Seite „Briefings“ (Seite briefings), vorbereitet. Bleibt unsichtbar, bis die Seite freigegeben ist:
  // dann BRIEFINGS_SEITE_FREI auf true setzen (kein toter Link vorher).
  // Migration 177 (B10b): Seite Briefings da; Link, wenn die Person sie öffnen darf (talents_briefing_kachel)
  const BRIEFINGS_SEITE_FREI = !!(D.wb && D.wb.seite === true);
  // Koordinator 30.10.2026: eine neue Analyse startet hier nur als Link zur Seite (Einstellungen zuerst), kein Knopf, der sofort etwas erzeugt
  if (BRIEFINGS_SEITE_FREI) inhaltWb.push({ typ: 'aktion', text: 'Neues Briefing', ziel: { seite: 'morgen-briefing', parameter: { neu: '1' } } },
    // Layout 1 (Plan 27, E7): Navigation als Textaktion, damit keine zwei Knöpfe unterschiedlicher Breite untereinander stehen
    { typ: 'aktion', art: 'link', text: 'Alle Briefings', ziel: { seite: 'morgen-briefing' } });
  abschnitte.push({ id: 'wochen-briefing', titel: 'Briefings', zahl: String(WB.length), offen_standard: !!erWahl,
    info: 'Deine Briefings mit Zahlen der Talents (höchstens fünf). Einstellen und lesen auf der Seite Briefing.', // Stefan 24.10.2026, 20:59: nur Information für den Nutzer
    inhalt: inhaltWb });
  // Text in Bausteine wie auf der Seite Benachrichtigungen (ALLY 34): Absätze; mehrzeilige Absätze mit kurzer erster Zeile = Überschrift und Liste
  const bausteine = t => {
    const aus = [];
    for (const abs of String(t || '').split(/\n{2,}/)) {
      const z = abs.split('\n').map(x => x.trim()).filter(Boolean);
      if (!z.length) continue;
      if (z.length === 1) { aus.push({ typ: 'text', text: z[0] }); continue; }
      let start = 0;
      if (/:$/.test(z[0]) || (z[0].length <= 60 && !/^[-•]/.test(z[0]))) { aus.push({ typ: 'unterueberschrift', text: z[0].replace(/:$/, '') }); start = 1; }
      aus.push({ typ: 'liste', eintraege: z.slice(start).map(x => ({ text: x.replace(/^[-•]\s*/, '') })) });
    }
    return aus.length ? aus : [{ typ: 'text', ton: 'grau', text: 'Kein Text gespeichert.' }];
  };
  const sel = null;  // Migration 180: Ergebnisse stehen mit Kopf und vollem Text auf der Seite KI-Analysen (kein Seitenfenster mehr)
  if (sel) fensterWb.push({ id: 'wochen-briefing', art: 'seitenfenster', offen: true, titel: String(sel.titel || 'Briefing'), untertitel: 'Briefing' + (sel.zeit ? ' · ' + String(sel.zeit) : ''),
    schliessen_ziel: hierWb({}), inhalt: bausteine(sel.text) });
}

// ---------- Kacheln „Kampagnen“ und „Reports“ (Stefan 24.10.2026, 21:05–21:09) ----------
// Feste Kacheln oben neben „Meldungen“ und „Briefings“: Zahl (laufende Kampagnen bzw. erstellte Reports), aufgeklappt die drei neuesten und ein Knopf zur Seite.
// Nur mit Zugang zur jeweiligen Seite (Daten laden: kp, rp – Rechte wie dort). Mit gewähltem Talent entfallen sie wie die übrigen Kacheln.
// Kampagnen aus Testdaten: wie auf der Seite Kampagnen mit „(Testdaten)“, bei „Testdaten ausblenden“ ohne sie (die Zahl enthält sie wie die Kennzahl dort).
const TDk = D.testdaten && typeof D.testdaten === 'object' && D.testdaten.aktiv === true ? D.testdaten : null;
const kTest = new Set((TDk && Array.isArray(TDk.kampagnen) ? TDk.kampagnen : []).map(String));
const kRaus = !!TDk && TDk.ausblenden === true && TDk.selbst_test !== true;
const KP = D.kp && typeof D.kp === 'object' ? D.kp : null;
if (KP) {
  const KST = { laufend: ['läuft', 'ok'], geplant: ['geplant', 'grau'], beendet: ['beendet', 'grau'], abgebrochen: ['abgebrochen', 'warn'] };
  const kNeu = (Array.isArray(KP.neu) ? KP.neu : []).filter(k => k && /^[0-9]{1,9}$/.test(String(k.id)) && !(kRaus && kTest.has(String(k.id)))).slice(0, 3);
  abschnitte.push({ id: 'kampagnen', titel: 'Kampagnen', zahl: zahl(Number(KP.laufend) || 0) + ' laufend', offen_standard: false, inhalt: [
    { typ: 'liste', leer: 'Noch keine Kampagnen.', eintraege: kNeu.map(k => { const s = KST[k.status] || KST.beendet;
      return { marke: { text: s[0], ton: s[1] }, text: String(k.titel || '') + (kTest.has(String(k.id)) ? ' (Testdaten)' : ''), neben: String(k.zeitraum || ''),
        ziel: { seite: 'kampagnen', parameter: { kampagne: String(k.id) } }, ziel_text: 'Öffnen' }; }) },
    { typ: 'aktion', text: 'Kampagnen öffnen', ziel: { seite: 'kampagnen' } }] });
}
// Reports wie in der Liste „Erstellte Reports“ (ALLY 27): Titel, Art, erstellt; fertige Reports „PDF herunterladen“ über die Seite „datei“ (tr = Report);
// fehlgeschlagene mit derselben Marke wie in der Liste (Koordinator 24.10.2026, 21:45)
const RP = D.rp && typeof D.rp === 'object' ? D.rp : null;
if (RP) {
  const rNeu = (Array.isArray(RP.zeilen) ? RP.zeilen : []).filter(x => x && /^[0-9]{1,12}$/.test(String(x.id))).slice(0, 3);
  abschnitte.push({ id: 'reports', titel: 'Reports', zahl: zahl(Number(RP.anzahl) || 0) + ' erstellt', offen_standard: false, inhalt: [
    { typ: 'liste', leer: String(RP.leer_text || 'Noch keine Reports erstellt.'), eintraege: rNeu.map(x => Object.assign({ fett: String(x.titel || ''), text: String(x.art_name || ''),
      neben: String(x.erstellt_text || '') }, x.status === 'fehler' ? { marke: { text: String(x.status_text || ''), ton: 'warn' } } : {}, x.herunterladen ? { ziel: { seite: 'datei', parameter: { tr: String(x.id) } }, ziel_text: 'PDF herunterladen' } : {})) },
    { typ: 'aktion', text: 'Reports öffnen', ziel: { seite: 'talent-reports' } }] });
}

// ---------- Archiv ----------
const fenster = fensterWb;
// A–Z Punkt 2 (Koordinator 23.10.2026): Suche im Archiv mit derselben Suche wie „Alle Talents“ (Name, Künstlername, Mail, Accounts), eigener Parameter aq
const aq = String(P.aq || '').trim().toLowerCase().slice(0, 100);
const archivG = aq ? archiv.filter(t => (name(t) + ' ' + (t.name || '') + ' ' + (t.kuenstlername || '') + ' ' + (t.email || '') + ' ' + kanaele(t).map(k => k.extern_name || '').join(' ')).toLowerCase().includes(aq.replace(/^@/, ''))) : archiv;
const arSeite = blattVon('archiv', archivG.length), arTeil = archivG.slice((arSeite - 1) * 20, arSeite * 20);
abschnitte.push({ id: 'archiv', titel: 'Archiv', zahl: String(archivG.length), offen_standard: !!aq, inhalt: [
  { typ: 'filter', id: 'archiv', label: 'Archiv durchsuchen', felder: [{ typ: 'suche', name: 'aq', label: 'Suche', platzhalter: 'Name oder @Account', wert: String(P.aq || '').slice(0, 100) }] },
  { typ: 'tabelle', id: 'archiv', titel: 'Archiv',
  spalten: [{ schluessel: 'name', titel: 'Talent' }, { schluessel: 'seit', titel: 'Archiviert am' }, { schluessel: 'loeschen', titel: 'Löschung frühestens' }, { schluessel: 'aktion', titel: 'Aktion' }],
  zeilen: arTeil.map(t => ({ zellen: { name: { text: name(t), ziel: profil(t) }, seit: String(t.archiviert_am || '–'), loeschen: t.loeschen_am ? { marke: { text: String(t.loeschen_am), ton: 'warn' } } : '–',
    aktion: verw ? Object.assign({ aktion: { text: 'Reaktivieren', aktion: 'tl_talent_reaktivieren', werte: { id: t.id } } }, adm ? { text: 'Löschen', fenster: 'loeschen-' + t.id } : {}) : '' } })),
  sortierung: {}, seite: arSeite, je_seite: 20, gesamt: archivG.length, leer: aq ? 'Keine archivierten Talents für diese Suche.' : 'Keine archivierten Talents.' }] });
if (adm) for (const t of arTeil) fenster.push({ id: 'loeschen-' + t.id, art: 'dialog', titel: name(t) + ' löschen', inhalt: [
  { typ: 'hinweis', ton: 'warn', text: 'Löscht das Talent mit allen Zahlen, Beiträgen und Notizen endgültig.' },
  { typ: 'formular', id: 'loeschen-' + t.id, aktion: 'tl_talent_loeschen', werte: { id: t.id }, felder: [{ typ: 'text', name: 'bestaetigung', label: 'Zur Bestätigung eingeben: ' + String(t.loeschen_bestaetigung || 'löschen'), pflicht: true, autocomplete: 'off' }],
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Endgültig löschen' }] }] });

// ---------- Kopf: Aktionen, Talent einladen, Import ----------
// B5c (Migration 165, Stefan G10): Rolle beim Einladen und Import vorbelegt mit Talent (nur Rollen für Talents)
const rolleFeld = (RL, info) => RL.length ? [{ typ: 'auswahl', name: 'rolle', label: 'Rolle', breite: 'voll', ausklappliste: true,
  wert: String((RL.find(r => r.wert === 'talent') || RL[0] || {}).wert || ''), optionen: RL.map(r => ({ wert: String(r.wert), text: String(r.text || r.wert) })), info }] : [];
const RL = Array.isArray(W.talent_rollen) ? W.talent_rollen : [];
const RINFO = 'Gilt, sobald das Talent einen Zugang bekommt. Beim Einrichten des Zugangs im Talent-Profil lässt sie sich ändern.';
if (anlegen && !verw) {
  kopf.hauptaktion = { text: 'Talent einladen', fenster: 'einladen' };
  fenster.push({ id: 'einladen', art: 'dialog', titel: 'Talent einladen', inhalt: [{ typ: 'formular', id: 'einladen', aktion: 'tl_talent_neu', spalten: 2, felder: [
    { typ: 'text', name: 'name', label: 'Name', autocomplete: 'off' }, { typ: 'text', name: 'kuenstlername', label: 'Künstlername', autocomplete: 'off' },
    { typ: 'email', name: 'email', label: 'E-Mail-Adresse', breite: 'voll', autocomplete: 'off' },
    { typ: 'mehrfach', name: 'kanaele', label: 'Accounts', breite: 'voll', wert: [], optionen: plattformen.map(p => ({ wert: p.schluessel, text: String(p.name || p.schluessel) })) }]
    .concat(rolleFeld(RL, RINFO), [{ typ: 'textbereich', name: 'notiz', label: 'Notiz', breite: 'voll', zeilen: 3, info: 'Du wirst als Manager oder Managerin des Talents eingetragen.' }]),
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Einladen' }] }] });
}
if (verw) {
  kopf.hauptaktion = { text: 'Talent einladen', fenster: 'einladen' };
  // E1/E2 (Stefan 24.10.2026, 16:03/16:05): „Talents importieren“ (bisher „Daten importieren“) bleibt im Menü; „Neue Links für abgelaufene Verbindungen“ steht jetzt in der Kachel „Einladungen“
  kopf.aktionen = [{ text: 'Talents importieren', fenster: 'import' }, { text: 'Archiv', ziel: { seite: 'talents', anker: 'a-archiv' } }];
  const pers = personen.filter(p => p.hat_recht);
  fenster.push({ id: 'einladen', art: 'dialog', titel: 'Talent einladen', inhalt: [{ typ: 'formular', id: 'einladen', aktion: 'tl_talent_neu', spalten: 2, felder: [
    { typ: 'text', name: 'name', label: 'Name', autocomplete: 'off' }, { typ: 'text', name: 'kuenstlername', label: 'Künstlername', autocomplete: 'off' },
    { typ: 'email', name: 'email', label: 'E-Mail-Adresse', breite: 'voll', autocomplete: 'off' },
    { typ: 'mehrfach', name: 'kanaele', label: 'Accounts', breite: 'voll', wert: [], optionen: plattformen.map(p => ({ wert: p.schluessel, text: String(p.name || p.schluessel) })) },
    { typ: 'mehrfach', name: 'personen', label: 'Manager/in', breite: 'voll', wert: (W.standard_zustaendig || []).map(String), optionen: pers.map(p => ({ wert: p.id, text: String(p.name || '') })) }]
    .concat(rolleFeld(RL, RINFO), [{ typ: 'textbereich', name: 'notiz', label: 'Notiz', breite: 'voll', zeilen: 3 }]),
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Einladen' }] }] });
  fenster.push({ id: 'import', art: 'dialog', titel: 'Talents importieren', inhalt: [{ typ: 'formular', id: 'import', aktion: 'ti_import_pruefen', datei: true, felder: [
    { typ: 'datei', name: 'datei', label: 'Tabelle (CSV)', accept: '.csv,text/csv', pflicht: true }].concat(rolleFeld(RL, 'Gilt für alle Talents dieser Tabelle, sobald sie einen Zugang bekommen.')),
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Prüfen' }] }] });
}
// C: mit gewähltem Talent nur die Liste „Alle Talents“ (das Archiv bleibt für den Papierkorb, der es weiterverarbeitet), ohne Gesamt-Kennzahlen und Kacheln.
// E2: ohne die Kachel „Einladungen“ (Talent gewählt oder keine offenen Einladungen) steht „Neue Links erstellen“ im Aktionen-Menü, damit es erreichbar bleibt.
if ((tw || !eingeladen.length) && verw) kopf.aktionen.splice(1, 0, { text: 'Neue Links erstellen', aktion: 'tl_links_erneuern', frage: 'Für alle abgelaufenen Verbindungen und Einladungen neue Links erstellen?' });
if (tw) { const bleibt = abschnitte.filter(a => a.id === 'meine' || a.id === 'alle' || a.id === 'archiv'); abschnitte.length = 0; abschnitte.push(...bleibt); }
return [{ json: { inhalt: Object.assign({ seite: kopf, abschnitte, fenster }, tw ? {} : { ueberblick }) } }];

// Parameter (ALLY 24): Sitzung für die Datenbank (nur 64 Hex-Zeichen, sonst leer = nicht angemeldet).
// Migration 65 (Stefan 20.10.2026, 09:23): Filter „Manuelle Daten“ (?manuell=0 nimmt sie heraus; Standard = einbeziehen).
// Punkt 5e (Stefan 21.10.2026): Zeitraum wie in ALLY 8 (zeitraum = 7tage|28tage|monat|vormonat|frei, bei frei von/bis); prüft die Datenbank (talents_zeitraum).
// „Eigener Zeitraum“ ohne Datum: Vorgabe die letzten 28 Tage bis gestern, damit Von und Bis sofort erscheinen und der Zeitraum nicht auf 28 Tage zurückspringt.
const E = $input.first().json;
const P = E.parameter || {};
const iso = v => /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(v || '')) ? String(v) : '';
const tag = d => new Date(d).toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
const f = {};
if (/^(7tage|28tage|monat|vormonat|frei)$/.test(String(P.zeitraum || ''))) f.zeitraum = String(P.zeitraum);
if (f.zeitraum === 'frei') {
  f.von = iso(P.von) || tag(Date.now() - 28 * 864e5);
  f.bis = iso(P.bis) || tag(Date.now() - 864e5);
}
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', String(P.manuell || '') === '0' ? '0' : '1', JSON.stringify(f)] } }];

// Werkzeug-Parameter (ALLY 24, BA10 Teil 3, Migration 71): Unteransichten der Talents w = import, texte, anfrage (sonst gilt die bisherige Seite, „Werkzeug?“).
// Nur geprüfte Werte: Nummern nur als Ziffern, Seiten der Tabellen aus p (import) bzw. blatt (texte, anfrage), nf = nur Zeilen mit Fehler.
const E = $('Start').first().json;
const P = E.parameter || {}, SE = E.seiten || {};
const w = ['import', 'texte', 'anfrage'].includes(String(P.w || '')) ? String(P.w) : '';
const z9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const s4 = v => /^[0-9]{1,4}$/.test(String(v ?? '')) && Number(v) >= 1 ? String(Number(v)) : '';
const ohneLeer = o => Object.fromEntries(Object.entries(o).filter(x => x[1] !== '' && x[1] !== undefined));
const filter = w === 'import' ? ohneLeer({ seite: s4(SE.import), nur_fehler: String(P.nf || '') === '1' ? '1' : '' })
  : w === 'texte' ? ohneLeer({ text_id: z9(P.text), seite: s4(P.blatt) })
  : w === 'anfrage' ? ohneLeer({ anfrage_id: z9(P.anfrage), seite: s4(P.blatt) }) : {};
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', w, w === 'import' ? z9(P.import) : '', JSON.stringify(filter)] } }];

// Werkzeug beschreiben (ALLY 24, BA10 Teil 3, Migration 71, Stefan 20.10.2026): Unteransichten der Talents wie ALLY 8 („Talents einsetzen“ Import,
// „Talents-Werkzeuge einsetzen“ Textentwürfe und Markenanfragen), Inhalte und Aktionen unverändert, Darstellung mit dem Baukasten (nur JSON):
// - w=import: Tabelle (CSV) hochladen (ti_import_pruefen, Datei an app/datei), Vorlage als Datei (ti_csv), geprüfte Tabellen, Vorschau mit Prüfergebnis je Zeile
//   (Seiten, nur Zeilen mit Fehler), „n Talents anlegen“ (ti_import_anlegen) und „Verwerfen“ (ti_import_verwerfen) mit Rückfrage, Ergebnis mit Einladungslinks und CSV.
// - w=texte: Textentwürfe ohne Talent (tx_erstellen, tx_speichern, tx_loeschen, me_anlegen als Entwurf); KI nur auf Klick „Text erstellen lassen“.
// - w=anfrage: Markenanfragen (ma_starten); KI nur auf Klick „Passende Talents finden“.
// Texte zu Meldungen, Fehlern und Zuständen setzt die Datenbank. Ally verschickt nichts: Mails nur als Entwurf im Entwurfsordner.
const E = $('Start').first().json;
const D = $input.first().json || {};
const F = E.funktion || {};
const P = E.parameter || {};
const W = String(D.w || '');
const PN = String(D.produkt_name || '').trim(), WER = PN || 'Der Assistent';
const LI = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const ganz = v => { const x = Number(v); return isFinite(x) ? Math.round(x) : 0; };
const mz = (n, eins, mehr) => ganz(n) + ' ' + (ganz(n) === 1 ? eins : mehr);
const name0 = String(F.name || 'Dashboard');
const talentsZiel = { seite: 'talents' };
const hier = (extra, anker) => ({ seite: 'talents', parameter: Object.assign({ w: W }, extra || {}), anker });
const KI_INFO = 'Vorschlag der KI auf Basis der gespeicherten Daten. Bitte prüfen.';
const kopf = (titel, beschreibung, krumeTitel) => ({ schluessel: 'talents', art: 'funktion', titel, beschreibung,
  krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: name0, ziel: talentsZiel }].concat(krumeTitel || [{ text: titel }]) });
const fehlerSeite = (titel, text) => [{ json: { inhalt: { seite: kopf(titel, ''), abschnitte: [{ id: 'fehler', titel, offen_standard: true,
  inhalt: [{ typ: 'text', ton: 'warn', text: String(text || 'Die Daten konnten nicht geladen werden. Bitte die Seite neu laden.') }, { typ: 'aktion', text: 'Zu den Talents', ziel: talentsZiel }] }] } } }];
// Blättern ohne Gesamtzahl (die Datenbank liefert Seite und Seiten): Links „Neuere“ und „Ältere“
const blaettern = (R, extra, anker) => { const s = Math.max(1, ganz(R.seite) || 1), n = Math.max(1, ganz(R.seiten) || 1); const a = [];
  if (s > 1) a.push({ typ: 'aktion', text: 'Vorherige Seite', ziel: hier(Object.assign({}, extra || {}, { blatt: String(s - 1) }), anker) });
  if (s < n) a.push({ typ: 'aktion', text: 'Nächste Seite (' + (s + 1) + ' von ' + n + ')', ziel: hier(Object.assign({}, extra || {}, { blatt: String(s + 1) }), anker) });
  return a; };
const postfachFeld = PF => ({ typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: String((PF.find(p => p.standard === true) || PF[0] || {}).adresse || ''),
  optionen: PF.map(p => ({ wert: String(p.adresse), text: p.name && p.name !== p.adresse ? String(p.name) + ' (' + p.adresse + ')' : String(p.adresse) })) });

// ========== Import ==========
if (W === 'import') {
  const IM = D.im || null;
  const titel = 'Talents importieren';
  if (!IM || IM.ok !== true) return fehlerSeite(titel, IM && IM.fehler);
  const verschl = D.verschl === true;
  const abschnitte = [], fenster = [];
  if (!IM.import) {
    const OF = LI(IM.offen).filter(o => id9(o.import_id)), vl = IM.vorlage && typeof IM.vorlage === 'object' ? IM.vorlage : null;
    const hoch = [];
    if (!verschl) hoch.push({ typ: 'text', ton: 'warn', text: 'Einladungen sind erst möglich, wenn die Verschlüsselung eingerichtet ist.' });
    hoch.push({ typ: 'formular', id: 'import-datei', aktion: 'ti_import_pruefen', datei: true, zurueck_ziel: hier({}, 'a-offen'), info: String(IM.erklaerung || ''),
      felder: [{ typ: 'datei', name: 'datei', label: 'Tabelle (CSV)', accept: '.csv,text/csv,text/plain', pflicht: true,
        info: 'Trennzeichen: Semikolon, Komma oder Tabulator. Vor dem Anlegen zeigt ' + WER + ' eine Vorschau mit Prüfung.' }]
        // B5c (Migration 165, Stefan G10): eine Rolle für alle Talents der Tabelle, vorbelegt mit Talent
        .concat(LI(IM.rollen).length ? [{ typ: 'auswahl', name: 'rolle', label: 'Rolle', breite: 'voll', ausklappliste: true,
          wert: String((LI(IM.rollen).find(r => r.wert === 'talent') || LI(IM.rollen)[0] || {}).wert || ''), optionen: LI(IM.rollen).map(r => ({ wert: String(r.wert), text: String(r.text || r.wert) })),
          info: 'Gilt für alle Talents dieser Tabelle, sobald sie einen Zugang bekommen.' }] : []),
      knoepfe: [{ text: 'Tabelle prüfen' }] });
    if (vl) hoch.push({ typ: 'formular', id: 'import-vorlage', aktion: 'ti_csv', werte: { art: 'vorlage' }, knoepfe: [{ text: 'Vorlage herunterladen (CSV)', art: 'neben' }] });
    abschnitte.push({ id: 'hochladen', titel: 'Tabelle hochladen', offen_standard: true, inhalt: hoch });
    abschnitte.push({ id: 'offen', titel: 'Geprüfte Tabellen', zahl: String(OF.length), offen_standard: true, info: 'Noch nicht angelegt. Geprüfte Tabellen werden nach 7 Tagen gelöscht.',
      inhalt: [{ typ: 'tabelle', id: 'offen', titel: 'Geprüfte Tabellen', spalten: [{ schluessel: 'hoch', titel: 'Hochgeladen' }, { schluessel: 'zeilen', titel: 'Zeilen', ausrichtung: 'rechts' }],
        zeilen: OF.slice(0, 10).map(o => ({ zellen: { hoch: { text: 'Hochgeladen am ' + String(o.erstellt || '–'), ziel: hier({ import: String(o.import_id) }) }, zeilen: mz(o.anzahl, 'Zeile', 'Zeilen') } })),
        sortierung: {}, seite: 1, je_seite: 10, gesamt: Math.min(OF.length, 10), leer: 'Keine geprüften Tabellen.' }] });
    return [{ json: { inhalt: { seite: kopf(titel, 'Talents aus einer Tabelle anlegen, je Talent mit Einladungslink.'), abschnitte, fenster } } }];
  }
  const im = IM.import, fi = IM.filter || {}, iid = id9(im.id), ZL = LI(IM.zeilen);
  const nurF = fi.nur_fehler === true || fi.nur_fehler === '1', angelegt = im.angelegt === true || !!im.angelegt_am;
  const t2 = angelegt ? 'Import angelegt' : 'Vorschau der Tabelle';
  const seite = kopf(t2, ['Hochgeladen am ' + String(im.erstellt || '–'), angelegt && im.angelegt_am ? 'angelegt am ' + im.angelegt_am : ''].filter(Boolean).join(' · '),
    [{ text: titel, ziel: hier({}) }, { text: angelegt ? 'Ergebnis' : 'Vorschau' }]);
  const kz = [{ label: 'Zeilen', wert: String(ganz(IM.anzahl_gesamt)) }, { label: 'Ohne Fehler', wert: String(ganz(IM.anzahl_ok)) },
    { label: 'Mit Fehler', wert: String(ganz(IM.anzahl_fehler)), ton: ganz(IM.anzahl_fehler) > 0 ? 'warn' : '' }].concat(angelegt ? [{ label: 'Angelegt', wert: String(ganz(IM.anzahl_angelegt)) }] : [],
    im.rolle_name ? [{ label: 'Rolle', wert: String(im.rolle_name) }] : []);   // B5c (Migration 165): Rolle der Talents dieser Tabelle
  const inhalt = [];
  if (!verschl) inhalt.push({ typ: 'text', ton: 'warn', text: 'Einladungen sind erst möglich, wenn die Verschlüsselung eingerichtet ist.' });
  if (ganz(IM.anzahl_fehler) > 0) inhalt.push({ typ: 'aktion', text: nurF ? 'Alle Zeilen zeigen' : 'Nur Zeilen mit Fehler zeigen (' + ganz(IM.anzahl_fehler) + ')',
    ziel: hier(nurF ? { import: iid } : { import: iid, nf: '1' }, 'a-zeilen') });
  inhalt.push({ typ: 'tabelle', id: 'import', titel: angelegt ? 'Angelegte Talents' : 'Zeilen der Tabelle',
    spalten: [{ schluessel: 'talent', titel: 'Talent' }, { schluessel: 'angaben', titel: 'Angaben' }, { schluessel: 'pruefung', titel: 'Prüfung' }],
    zeilen: ZL.map(z => ({ zellen: {
      talent: { text: [z.name, z.kuenstlername ? '(' + z.kuenstlername + ')' : ''].filter(Boolean).join(' ') || 'Ohne Namen', fett: true, neben: 'Zeile ' + String(z.zeile ?? '') },
      angaben: [z.email, z.kanaele_text ? 'Kanäle: ' + z.kanaele_text : '', z.personen_text ? 'Manager/in: ' + z.personen_text : ''].filter(Boolean).join(' · ') || '–',
      pruefung: { marke: { text: z.ergebnis ? (z.ergebnis === 'angelegt' ? 'angelegt' : 'übersprungen') : z.ok === true ? 'ohne Fehler' : 'Fehler', ton: z.ok === true ? 'ok' : 'warn' },
        text: z.ok !== true && z.fehler ? (Array.isArray(z.fehler) ? z.fehler.join(' ') : String(z.fehler)) : z.link ? String(z.link) : '',
        neben: z.link ? 'Einladungslink' + (z.gueltig_bis ? ', gültig bis ' + z.gueltig_bis : '') : '' } } })),
    sortierung: {}, seite: Math.max(1, ganz(IM.seite) || 1), je_seite: Math.max(1, ganz(IM.je_seite) || 10), gesamt: ganz(IM.anzahl), leer: nurF ? 'Keine Zeilen mit Fehler.' : 'Keine Zeilen.' });
  const hinweis = angelegt ? WER + ' verschickt nichts selbst. Bitte die Links an die Talents schicken. Links, die inzwischen abgelaufen sind, stehen nicht mehr in der Tabelle.'
    : ganz(IM.anzahl_ok) === 0 ? 'Keine Zeile ohne Fehler. Bitte die Tabelle korrigieren und neu hochladen.'
    : ganz(IM.anzahl_fehler) > 0 ? 'Zeilen mit Fehler werden übersprungen. Korrigieren geht in der Tabelle: verwerfen und neu hochladen.' : '';
  if (angelegt) {
    inhalt.push({ typ: 'formular', id: 'import-csv', aktion: 'ti_csv', werte: { art: 'import', import_id: iid }, knoepfe: [{ text: 'Tabelle mit Links herunterladen (CSV)', art: 'neben' }] });
    inhalt.push({ typ: 'aktion', text: 'Zu den Talents', ziel: talentsZiel });
  } else {
    if (IM.darf_anlegen === true && ganz(IM.anzahl_ok) > 0) seite.hauptaktion = { text: ganz(IM.anzahl_ok) === 1 ? '1 Talent anlegen' : ganz(IM.anzahl_ok) + ' Talents anlegen', aktion: 'ti_import_anlegen',
      werte: { import_id: iid }, frage: (ganz(IM.anzahl_ok) === 1 ? '1 Talent' : ganz(IM.anzahl_ok) + ' Talents') + ' anlegen? Jedes bekommt einen Einladungslink. Zeilen mit Fehler werden übersprungen.' };
    seite.aktionen = [{ text: 'Verwerfen', aktion: 'ti_import_verwerfen', werte: { import_id: iid }, frage: 'Diese Tabelle verwerfen? Angelegt wird nichts.' }];
  }
  abschnitte.push({ id: 'zeilen', titel: angelegt ? 'Angelegte Talents' : 'Zeilen der Tabelle', zahl: String(ganz(IM.anzahl)), offen_standard: true, info: hinweis || undefined, inhalt });
  return [{ json: { inhalt: { seite, ueberblick: { kennzahlen: kz }, abschnitte, fenster } } }];
}

// ========== Kommunikation › Textentwürfe (ohne Talent) ==========
if (W === 'texte') {
  const R = D.tx || null, titel = 'Textentwürfe';
  if (!R || R.ok !== true) return fehlerSeite(titel, R && R.fehler);
  const X = R.text && typeof R.text === 'object' ? R.text : null, xid = X ? id9(X.text_id) : '';
  const seite = kopf(titel, 'Entwürfe der KI für Mediakit, Kampagnenbericht und Antworten an Marken.');
  seite.hauptaktion = { text: 'Text erstellen', fenster: 'neu' };
  const abschnitte = [], fenster = [];
  const TL = LI(R.texte).filter(x => id9(x.text_id));
  abschnitte.push({ id: 'texte', titel: 'Texte', zahl: String(TL.length), offen_standard: true, info: 'Mediakit-Text, Kampagnen-Zusammenfassung, Antwort an eine Marke.',
    inhalt: [{ typ: 'tabelle', id: 'texte', titel: 'Texte', spalten: [{ schluessel: 'titel', titel: 'Titel' }, { schluessel: 'art', titel: 'Art' }, { schluessel: 'stand', titel: 'Stand' }],
      zeilen: TL.map(x => ({ aktiv: id9(x.text_id) === xid, zellen: { titel: { text: String(x.titel || 'Text'), ziel: hier({ text: id9(x.text_id), blatt: ganz(R.seite) > 1 ? String(ganz(R.seite)) : '' }) },
        art: [x.art_name, x.talent_name].filter(Boolean).join(' · ') || '–', stand: [x.status_text, x.datum].filter(Boolean).join(' · ') || '–' } })),
      sortierung: {}, seite: 1, je_seite: Math.max(1, TL.length), gesamt: TL.length, leer: 'Noch keine Texte.' }].concat(blaettern(R, {}, 'a-texte')) });
  const AR = LI(R.arten), KP = LI(R.kampagnen).filter(k => id9(k.kampagne_id)), AW = LI(D.talents_auswahl).filter(t => id9(t.id));
  const bra = AR.reduce((o, x) => (o[x.braucht] = (o[x.braucht] || []).concat(x.name), o), {});
  const felder = [{ typ: 'auswahl', name: 'art', label: 'Art', pflicht: true, wert: '', optionen: AR.map(x => ({ wert: String(x.wert), text: String(x.name) })) }];
  if (AW.length) felder.push({ typ: 'auswahl', name: 'talent_id', label: 'Talent', wert: '', optionen: [{ wert: '', text: '–' }].concat(AW.map(t => ({ wert: id9(t.id), text: String(t.anzeigename || '') }))),
    info: 'Für ' + (bra.talent || ['Mediakit-Text']).join(', ') + '.' });
  if (KP.length) felder.push({ typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', wert: '', optionen: [{ wert: '', text: '–' }].concat(KP.map(k => ({ wert: id9(k.kampagne_id),
    text: [k.titel || k.name, k.zeitraum_text].filter(Boolean).join(' · ') }))), info: 'Für ' + (bra.kampagne || ['die Zusammenfassung']).join(', ') + '.' });
  felder.push({ typ: 'textbereich', name: 'eingabe', label: 'Anfrage der Marke einfügen', breite: 'voll', zeilen: 6, info: 'Für ' + (bra.anfrage || ['die Antwort an eine Marke']).join(', ') + '.' });
  const neu = [];
  if (R.ki_hinweis) neu.push({ typ: 'text', ton: 'grau', text: String(R.ki_hinweis) });
  else neu.push({ typ: 'formular', id: 'text-neu', aktion: 'tx_erstellen', spalten: 2, felder, zurueck_ziel: hier({}, 'a-texte'),
    info: 'Die KI erstellt einen Entwurf aus den gespeicherten Daten. Sie arbeitet nur auf Anforderung; die Nutzung zählt zum KI-Budget.', knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Text erstellen lassen' }] });
  fenster.push({ id: 'neu', art: 'dialog', titel: 'Neuer Text', inhalt: neu });
  if (X) {
    const xi = [{ typ: 'paare', eintraege: [{ label: 'Art', wert: String(X.art_name || '–') }, { label: 'Talent', wert: String(X.talent_name || '–') }, { label: 'Stand', wert: String(X.status_text || '–') }] }];
    if (X.eingabe) xi.push({ typ: 'unterueberschrift', text: 'Anfrage der Marke' }, { typ: 'text', text: String(X.eingabe) });
    if (X.laeuft === true) xi.push({ typ: 'text', ton: 'grau', text: 'Der Text wird gerade erstellt. Bitte die Seite in etwa einer Minute neu laden.' });
    else if (X.status === 'fehler') xi.push({ typ: 'aktion', text: 'Löschen', aktion: 'tx_loeschen', werte: { text_id: xid }, frage: 'Diesen Text löschen?' });
    else {
      const hw = LI(X.hinweise).map(v => typeof v === 'string' ? v : (v && (v.text || v.zahl)) || '').filter(Boolean);
      if (hw.length) xi.push({ typ: 'text', ton: 'warn', text: 'Bitte prüfen: ' + hw.join(', ') });
      xi.push({ typ: 'formular', id: 'text-speichern', aktion: 'tx_speichern', werte: { text_id: xid }, info: KI_INFO, felder: [
        { typ: 'text', name: 'titel', label: 'Titel', wert: String(X.titel || ''), breite: 'voll' },
        { typ: 'textbereich', name: 'text', label: 'Text', wert: String(X.text || ''), zeilen: 12, breite: 'voll' }], knoepfe: [{ text: 'Speichern' }] });
      xi.push({ typ: 'aktion', text: 'Löschen', aktion: 'tx_loeschen', werte: { text_id: xid }, frage: 'Diesen Text löschen?' });
      const PF = LI(R.postfaecher).filter(p => p && p.adresse);
      if (X.als_mail_moeglich === true) {
        xi.push({ typ: 'unterueberschrift', text: 'Als Mail-Entwurf ablegen', info: WER + ' legt die Mail nur als Entwurf im Entwurfsordner ab. Verschickt wird sie nur von dir.' });
        if (PF.length) xi.push({ typ: 'formular', id: 'text-mail', aktion: 'me_anlegen', werte: { art: 'antwort_marke', text_id: xid, talent_id: id9(X.talent_id) }, spalten: 2, felder: [
          { typ: 'email', name: 'an', label: 'An (E-Mail der Marke)', pflicht: true, autocomplete: 'off' }, { typ: 'text', name: 'an_name', label: 'Name der Marke' }, postfachFeld(PF)],
          knoepfe: [{ text: 'Entwurf ablegen', art: 'neben' }] });
        else xi.push({ typ: 'text', ton: 'grau', text: 'Kein Postfach mit eingeschalteten Mail-Entwürfen.' });
      }
    }
    fenster.push({ id: 'text', art: 'seitenfenster', offen: true, titel: String(X.titel || 'Text'), untertitel: String(X.art_name || ''), schliessen_ziel: hier({}, 'a-texte'), inhalt: xi });
  }
  return [{ json: { inhalt: { seite, abschnitte, fenster } } }];
}

// ========== Kampagnen › Markenanfragen ==========
if (W === 'anfrage') {
  const R = D.an || null, titel = 'Markenanfragen';
  if (!R || R.ok !== true) return fehlerSeite(titel, R && R.fehler);
  const AN = R.anfrage && typeof R.anfrage === 'object' ? R.anfrage : null, qid = AN ? id9(AN.anfrage_id) : '';
  const AW = LI(D.talents_auswahl).filter(t => id9(t.id));
  const seite = kopf(titel, 'Welche Talents passen zu einer Anfrage? ' + WER + ' schreibt keine Marke an. Den Entwurf schickst nur du.');
  seite.hauptaktion = { text: 'Neue Anfrage', fenster: 'neu' };
  const abschnitte = [], fenster = [];
  const AL = LI(R.anfragen).filter(x => id9(x.anfrage_id));
  abschnitte.push({ id: 'anfragen', titel: 'Bisherige Anfragen', zahl: String(AL.length), offen_standard: true, info: 'Eingefügte und aus Mails erkannte Anfragen.',
    inhalt: [{ typ: 'tabelle', id: 'anfragen', titel: 'Bisherige Anfragen', spalten: [{ schluessel: 'marke', titel: 'Marke' }, { schluessel: 'datum', titel: 'Datum und Quelle' }, { schluessel: 'stand', titel: 'Stand' }],
      zeilen: AL.map(x => ({ aktiv: id9(x.anfrage_id) === qid, zellen: { marke: { text: String(x.marke || 'Anfrage'), ziel: hier({ anfrage: id9(x.anfrage_id), blatt: ganz(R.seite) > 1 ? String(ganz(R.seite)) : '' }) },
        datum: [x.datum, x.quelle_text].filter(Boolean).join(' · ') || '–', stand: String(x.status_text || '–') } })),
      sortierung: {}, seite: 1, je_seite: Math.max(1, AL.length), gesamt: AL.length, leer: 'Noch keine Anfragen.' }].concat(blaettern(R, {}, 'a-anfragen')) });
  const neu = [];
  if (R.ki_hinweis) neu.push({ typ: 'text', ton: 'grau', text: String(R.ki_hinweis) });
  else {
    const felder = [{ typ: 'textbereich', name: 'anfrage', label: 'Anfrage der Marke (Mail oder Nachricht einfügen)', pflicht: true, zeilen: 6, breite: 'voll' }];
    if (AW.length) felder.push({ typ: 'mehrfach', name: 'ausschliessen', label: 'Diese Talents nicht vorschlagen (optional)', breite: 'voll', wert: [], optionen: AW.map(t => ({ wert: id9(t.id), text: String(t.anzeigename || '') })) });
    neu.push({ typ: 'formular', id: 'anfrage-neu', aktion: 'ma_starten', felder, zurueck_ziel: hier({}, 'a-anfragen'),
      info: 'Die KI schlägt passende Talents mit Begründung vor. Sie arbeitet nur auf Anforderung; die Nutzung zählt zum KI-Budget.', knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Passende Talents finden' }] });
  }
  fenster.push({ id: 'neu', art: 'dialog', titel: 'Neue Anfrage', inhalt: neu });
  if (AN) {
    const x = [{ typ: 'paare', eintraege: [{ label: 'Eingang', wert: [AN.erstellt, AN.quelle === 'mail' ? 'aus einer Mail' : 'eingefügt'].filter(Boolean).join(' · ') || '–' },
      { label: 'Marke', wert: String(AN.marke || '–') }, { label: 'Branche', wert: String(AN.branche || '–') }] }];
    if (AN.laeuft === true) x.push({ typ: 'text', ton: 'grau', text: String(AN.status_text || 'Wird bearbeitet. Bitte die Seite in etwa einer Minute neu laden.') });
    else if (AN.status === 'fehler') x.push({ typ: 'text', ton: 'warn', text: String(AN.status_text || 'Fehler') });
    else {
      if (AN.status_text) x.push({ typ: 'text', ton: 'grau', text: String(AN.status_text) });
      const VS = LI(AN.vorschlaege);
      x.push({ typ: 'unterueberschrift', text: 'Vorschläge', info: VS.length ? KI_INFO : undefined });
      x.push({ typ: 'tabelle', id: 'vorschlaege', titel: 'Vorschläge', spalten: [{ schluessel: 'talent', titel: 'Talent' }, { schluessel: 'passung', titel: 'Passung' }, { schluessel: 'grund', titel: 'Begründung' }],
        zeilen: VS.map(v => ({ zellen: { talent: id9(v.talent_id) ? { text: String(v.name || 'Talent'), ziel: { seite: 'talent', parameter: { id: id9(v.talent_id) } } } : { text: String(v.name || ''), fett: true },
          passung: { marke: { text: String(v.passung_text || ''), ton: v.passung === 'gut' ? 'ok' : 'grau' } }, grund: String(v.begruendung || '') } })),
        sortierung: {}, seite: 1, je_seite: Math.max(1, VS.length), gesamt: VS.length, leer: 'Keine passenden Talents.' });
      const AU = LI(AN.ausgeschlossen);
      if (AU.length) x.push({ typ: 'unterueberschrift', text: 'Nicht vorgeschlagen (' + AU.length + ')' }, { typ: 'liste', eintraege: AU.map(v => ({ fett: String(v.name || ''), text: String(v.grund || '') })) });
      const AT = AN.antwort && typeof AN.antwort === 'object' ? AN.antwort : null;
      if (AT) {
        x.push({ typ: 'unterueberschrift', text: 'Antwort-Entwurf' }, { typ: 'text', ton: 'grau', text: String(AT.status_text || '') });
        if (AT.text) x.push({ typ: 'text', text: String(AT.text) });
        if (id9(AT.text_id)) x.push({ typ: 'aktion', text: 'Bearbeiten', ziel: id9(AT.talent_id) ? { seite: 'talent', parameter: { id: id9(AT.talent_id), w: 'texte', text: id9(AT.text_id) } }
          : { seite: 'talents', parameter: { w: 'texte', text: id9(AT.text_id) } } });
      }
    }
    x.push({ typ: 'unterueberschrift', text: 'Anfrage der Marke' }, { typ: 'text', text: String(AN.anfrage || '') });
    fenster.push({ id: 'anfrage', art: 'seitenfenster', offen: true, titel: 'Anfrage' + (AN.marke ? ' von ' + AN.marke : ''), schliessen_ziel: hier({}, 'a-anfragen'), inhalt: x });
  }
  return [{ json: { inhalt: { seite, abschnitte, fenster } } }];
}
return fehlerSeite(name0, 'Diese Ansicht gibt es nicht.');

// Werkzeug-Ergänzung (ALLY 24, BA10 Teil 3, Migration 71, Stefan 20.10.2026): ergänzt die fertige Seite Talents, ohne „Seite beschreiben“ zu ändern.
// Kopf › Aktionen: Markenanfragen (Unteransicht w=anfrage; Textentwürfe w=texte seit E3 nicht mehr im Menü); „Daten importieren“ öffnet die Importseite (w=import: Vorlage, geprüfte Tabellen,
// Vorschau, Anlegen, Verwerfen) statt nur des Hochlade-Fensters. Neue Einladungslinks (nach „Neue Links für abgelaufene Verbindungen“) als Abschnitt mit Tabelle und CSV.
const aus = $('Seite beschreiben').all().map(x => x.json);
const L = ($input.first() || {}).json ? ($input.first().json.links || null) : null;
// Zeilen der CSV der neuen Links lesen (Kopfzeile Name;E-Mail;Link;gültig bis, Felder in "…", wie ALLY 8 „CSV-Anfrage lesen“ sie prüft)
const zeilenAus = csv => {
  const t = String(csv || '').replace(/^﻿/, '').replace(/\r\n?/g, '\n').replace(/\n+$/, '');
  const z = t.split('\n'), FELD = /"((?:[^"]|"")*)"/g, out = [];
  for (const zeile of z.slice(1, 601)) { const f = [...zeile.matchAll(FELD)].map(m => m[1].replace(/""/g, '"')); if (f.length >= 4) out.push(f); }
  return out;
};
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !I.seite || !Array.isArray(I.abschnitte)) continue;
  const S = I.seite;
  const akt = Array.isArray(S.aktionen) ? S.aktionen : [];
  const imp = akt.findIndex(a => a && a.fenster === 'import');
  if (imp >= 0) {
    akt[imp] = { text: 'Talents importieren', ziel: { seite: 'talents', parameter: { w: 'import' } } };   // E1 (Stefan 24.10.2026, 16:05): bisher „Daten importieren“
    if (Array.isArray(I.fenster)) I.fenster = I.fenster.filter(f => !(f && f.id === 'import'));
  }
  // E3 (Stefan 24.10.2026, 16:39): „Textentwürfe“ nicht mehr im Menü der Seite Talents; die Ansicht w=texte und die Textentwürfe im Talent-Profil bleiben.
  akt.push({ text: 'Markenanfragen', ziel: { seite: 'talents', parameter: { w: 'anfrage' } } });
  S.aktionen = akt;
  if (L && typeof L === 'object' && typeof L.csv === 'string') {
    const Z = zeilenAus(L.csv);
    I.abschnitte.unshift({ id: 'neue-links', titel: 'Neue Einladungslinks', zahl: String(Z.length), offen_standard: true,
      info: 'Die Links stehen hier, bis du die nächste Aktion ausführst. Bitte an die Talents schicken; verschickt wird nichts automatisch.',
      inhalt: [{ typ: 'tabelle', id: 'neue-links', titel: 'Neue Einladungslinks', spalten: [{ schluessel: 'name', titel: 'Talent' }, { schluessel: 'email', titel: 'E-Mail' },
        { schluessel: 'link', titel: 'Link' }, { schluessel: 'bis', titel: 'Gültig bis' }],
        zeilen: Z.map(f => ({ zellen: { name: { text: f[0] || '–', fett: true }, email: f[1] || '–', link: f[2] || '–', bis: f[3] || '–' } })),
        sortierung: {}, seite: 1, je_seite: Math.max(1, Z.length), gesamt: Z.length, leer: 'Keine neuen Links.' },
        { typ: 'formular', id: 'links-csv', aktion: 'ti_csv', werte: { art: 'links' }, knoepfe: [{ text: 'Links herunterladen (CSV)', art: 'neben' }] }] });
  }
}
return aus.map(json => ({ json }));

// Export-Link (ALLY 24, BA10 Teil 4, Stefan 21.10.2026): ergänzt die Seite Talents, ohne „Seite beschreiben“ und „Werkzeug-Ergänzung“ zu ändern: Export der Talents (ZIP)
// wie ALLY 8 (nur mit „Talents verwalten“ und wenn es Talents gibt) – über Ally (Seite datei, tx; ALLY 20 prüft das Recht), nie ein Direktlink.
const aus = $input.all().map(x => x.json);
const W = ($('Daten laden').first().json || {}).d || {};
const alle = Array.isArray(W.talents) ? W.talents : [];
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !I.seite || typeof I.seite !== 'object' || W.darf_verwalten !== true || !alle.length) continue;
  // 2n (Stefan 24.10.2026, 16:52, bekräftigt 25.10.2026): kein „Exportieren“ mehr im Menü Aktionen – der Export steht an den Listen „Meine Talents“ und
  // „Alle Talents“ (Aktionen für markierte Zeilen immer an der Liste), nur für die markierten Zeilen; ohne Markierung kein Export (alles: „Alle markieren“).
  // Weiter über Ally (Seite datei, tx = Nummer oder „12,15“; ALLY 20 und Migration 146 prüfen Recht und Umfang, höchstens 1000), nie ein Direktlink.
  for (const ab of Array.isArray(I.abschnitte) ? I.abschnitte : []) {
    if (!ab || !['meine', 'alle'].includes(ab.id) || !Array.isArray(ab.inhalt)) continue;
    for (const b of ab.inhalt) if (b && b.typ === 'tabelle' && b.id === ab.id && Array.isArray(b.alle_ids))
      b.export = { text: 'Exportieren', ziel: { seite: 'datei', parameter: {} }, parameter: 'tx', hoechstens: 1000 };
  }
}
return aus.map(json => ({ json }));

// Punkt 5i (Stefan 21.10.2026): Einladung wie in ALLY 8 – Link, Betreff und Text zum Kopieren und „Im Mailprogramm öffnen“ (mailto; es wird nichts automatisch verschickt).
// Ergänzt nur die Tabelle „Einladungen“: Link mit Knopf „Kopieren“ und je Talent mit gültigem Link „Text und Mailprogramm“ (Fenster). Daten wie die Tabelle (talents_web_daten, Einladungstext
// aus talent_einladungstext: Vorlage der Agentur oder Standardtext). Ohne „Seite beschreiben“ zu ändern. Braucht den Baukasten mit kopieren, mailto und aktionen (ALLY 21).
const aus = $input.all().map(x => x.json);
const W = ($('Daten laden').first().json || {}).d || {};
const T = new Map((Array.isArray(W.talents) ? W.talents : []).map(t => [String(t.id), t]));
const name = t => String(t.anzeigename || t.name || ('Talent ' + t.id));
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.abschnitte)) continue;
  const ab = I.abschnitte.find(a => a && a.id === 'einladungen');
  const tab = ab && Array.isArray(ab.inhalt) ? ab.inhalt.find(b => b && b.typ === 'tabelle' && b.id === 'einladungen') : null;
  if (!tab) continue;
  I.fenster = Array.isArray(I.fenster) ? I.fenster : [];
  for (const z of (tab.zeilen || [])) {
    const zl = z && z.zellen ? z.zellen : null, ziel = zl && zl.name && zl.name.ziel;
    const tid = ziel && ziel.parameter ? String(ziel.parameter.id || '') : '';
    const t = /^[0-9]{1,9}$/.test(tid) ? T.get(tid) : null, ei = t && t.einladung;
    if (!ei || ei.abgelaufen === true || !ei.link || !zl.link || typeof zl.link !== 'object') continue;
    const link = String(ei.link), tx = ei.text && typeof ei.text === 'object' && ei.text.text ? ei.text : null, fid = 'einladung-' + tid;
    zl.link.kopieren = true; zl.link.kopieren_label = 'Einladungslink von ' + name(t) + ' kopieren';
    zl.link.aktionen = [{ text: 'Text und Mailprogramm', fenster: fid }].concat(zl.link.aktion ? [zl.link.aktion] : []);
    const felder = [{ typ: 'anzeige', name: 'link', label: 'Einladungslink', wert: link, kopieren: true, breite: 'voll',
      info: [ei.gueltig_bis ? 'Gültig bis ' + String(ei.gueltig_bis) + '.' : '', 'Es wird nichts automatisch verschickt: Link oder Text kopieren und dem Talent schicken.'].filter(Boolean) }];
    if (tx) felder.push({ typ: 'anzeige', name: 'betreff', label: 'Betreff', wert: String(tx.betreff || ''), kopieren: true, breite: 'voll' },
      { typ: 'anzeige', name: 'text', label: 'Einladungstext', wert: String(tx.text || ''), kopieren: true, mehrzeilig: true, breite: 'voll',
        info: tx.an ? undefined : 'Für dieses Talent ist keine E-Mail-Adresse hinterlegt. Die Empfängeradresse im Mailprogramm eintragen.' });
    const inhalt = [{ typ: 'formular', id: fid, felder }];
    if (tx) inhalt.push({ typ: 'aktion', text: 'Im Mailprogramm öffnen', art: 'neben', mailto: { an: String(tx.an || ''), betreff: String(tx.betreff || ''), text: String(tx.text || '') } });
    inhalt.push({ typ: 'aktion', text: 'Zum Talent', art: 'link', ziel });
    I.fenster.push({ id: fid, art: 'dialog', titel: 'Einladung für ' + name(t), inhalt });
  }
}
return aus.map(json => ({ json }));

