-- Testdaten-Kennung (ALLY 24, Migration 79, Stefan 21.10.2026): welche Talents, Kampagnen und Personen Testdaten sind und ob die Person sie ausgeblendet hat.
-- Ohne Testdaten nur {aktiv: false}. $1 Sitzung.
SELECT ally_testdaten_kennung($1::text) AS td;

parameters.jsCode:
// Testdaten filtern (ALLY 24, Migration 79, Stefan 21.10.2026): Hat die Person „Testdaten ausblenden“ gewählt (ally_testdaten_kennung, je Person gespeichert),
// fehlen Test-Talents und Test-Personen in Listen, Tabellen, Filtern und Zählern dieser Seite. Summen aus der Datenbank (Reichweite) enthalten sie weiter (Hinweis am Titel).
// Ohne Testdaten unverändert. Gibt die Daten wie „Daten laden“ weiter, dazu testdaten (für „Testdaten kennzeichnen“).
const D = Object.assign({}, $('Daten laden').first().json || {});
let TD = {};
try { TD = ($input.first().json || {}).td || {}; } catch (e) { TD = {}; }
if (TD && TD.aktiv === true && TD.ausblenden === true && D.d && typeof D.d === 'object') {
  const T = new Set((Array.isArray(TD.talents) ? TD.talents : []).map(String)), PE = new Set((Array.isArray(TD.personen) ? TD.personen : []).map(String));
  const W = Object.assign({}, D.d);
  if (Array.isArray(W.talents)) W.talents = W.talents.filter(t => !T.has(String(t && t.id)));
  if (Array.isArray(W.personen)) W.personen = W.personen.filter(p => !PE.has(String(p && p.id)));
  D.d = W;
  for (const k of ['zahlen', 'zahlen_offen']) if (D[k] && typeof D[k] === 'object') { const z = {}; for (const id of Object.keys(D[k])) if (!T.has(id)) z[id] = D[k][id]; D[k] = z; }
}
D.testdaten = TD && typeof TD === 'object' ? TD : {};
return [{ json: D }];

// Testdaten kennzeichnen (ALLY 24, Migration 79, Stefan 21.10.2026). Daten aus „Testdaten filtern“ (ally_testdaten_kennung).
const aus = $input.all().map(x => x.json);
let TD = {};
try { TD = ($('Testdaten filtern').first().json || {}).testdaten || {}; } catch (e) { TD = {}; }
if (!TD || TD.aktiv !== true) return aus.map(json => ({ json }));
// ---- gemeinsamer Teil „Testdaten kennzeichnen“ (Migration 79): kleine Marke „Testdaten“ an Talents, Kampagnen und Personen aus Testdaten,
// dazu im Seitenkopf unter „Aktionen“ „Testdaten ausblenden/einblenden“ (td_ausblenden, je Person) und ein Hinweis am Titel. Ohne Testdaten unverändert.
const MARKE = { text: 'Testdaten', ton: 'grau' };
const T = new Set((Array.isArray(TD.talents) ? TD.talents : []).map(String));
const K = new Set((Array.isArray(TD.kampagnen) ? TD.kampagnen : []).map(String));
const istTest = z => !!(z && typeof z === 'object' && z.parameter && typeof z.parameter === 'object' &&
  ((z.seite === 'talent' && T.has(String(z.parameter.id))) || (z.seite === 'kampagne' && K.has(String(z.parameter.id)))));
const geh = x => {
  if (Array.isArray(x)) { x.forEach(geh); return; }
  if (!x || typeof x !== 'object') return;
  if (x.zellen && typeof x.zellen === 'object') {
    for (const c of Object.values(x.zellen)) if (c && typeof c === 'object' && istTest(c.ziel) && !c.marke) c.marke = MARKE;
  } else if (x.titel_ziel && istTest(x.titel_ziel)) {
    if (!x.art) x.art = 'Testdaten'; else if (!/Testdaten/.test(String(x.art))) x.art = String(x.art) + ' · Testdaten';
  } else if (typeof x.text === 'string' && istTest(x.ziel) && x.typ === undefined && !x.aktion && !(x.marke && x.marke.text === 'Testdaten')) {
    if (!x.marke) { x.marke = MARKE; x.marke_hinten = true; } else if (!/Testdaten/.test(x.text)) x.text = x.text + ' (Testdaten)';
  }
  for (const k of Object.keys(x)) if (x[k] && typeof x[k] === 'object') geh(x[k]);
};
for (const j of aus) {
  if (!j || !j.inhalt) continue;
  geh(j.inhalt.abschnitte); geh(j.inhalt.bloecke); geh(j.inhalt.ueberblick); geh(j.inhalt.fenster);
  const S = j.inhalt.seite;
  if (S && typeof S === 'object' && TD.selbst_test !== true) {
    // E5 (Stefan 24.10.2026, 16:03): auf der Seite Talents kein „Testdaten ausblenden/einblenden“ mehr im Menü; die Marke „Testdaten“ bleibt.
    // Ein- und ausblenden geht weiter auf den Seiten Talent-Profil und Kampagnen (dieselbe Einstellung je Person).
    S.info = [].concat(S.info === undefined || S.info === null || S.info === '' ? [] : S.info,
      [TD.ausblenden === true ? 'Testdaten sind für dich ausgeblendet (auf dem Talent-Profil oder bei Kampagnen unter „Aktionen“ wieder einblenden). Summen und Kennzahlen aus allen Daten enthalten sie weiter.'
        : 'Einträge mit „Testdaten“ sind Beispieldaten zum Ausprobieren. Summen und Kennzahlen enthalten sie.']);
  }
}
return aus.map(json => ({ json }));

