parameters.jsCode:
// Talents mit Papierkorb (ALLY 24, Migration 130, E13 „Löschen = Papierkorb“; Entscheidungen des Koordinators 24.10.2026).
// Ergänzt die Seite Talents, ohne die Knoten davor zu ändern (Muster wie „Marketing (Papierkorb)“, Migration 133):
//   Aus „Archiv“ wird „Papierkorb“: Der Abschnitt Archiv verschwindet von der Liste, oben steht der Knopf „Papierkorb“ ohne Zähler (E9).
//   Unterseite papierkorb=1: die Talents im Papierkorb (Markierung = status archiviert, mit Suche und Löschfrist wie bisher) mit „Wiederherstellen“
//   (tl_talent_reaktivieren) und „Endgültig löschen“ (nur Admin, Namensbestätigung wie bisher), oben „Papierkorb leeren“ (nur Admin, tl_papierkorb_leeren:
//   genau die angezeigten Talents der Suche, höchstens 1000, Bestätigung mit dem Wort „löschen“). Dazu KI-Texte ohne Talent im Papierkorb (tp_*).
//   Nur der Papierkorb (ohne Überblick). Die Löschfrist mit Ankündigung bleibt unverändert (Spalte „Löschung frühestens“).
const E = $('Start').first().json;
const P = E.parameter || {};
const D = $('Testdaten filtern').first().json || {};
const W = D.d && typeof D.d === 'object' ? D.d : {};
const PL = ($input.first().json || {}).pk || null;
const LI = x => Array.isArray(x) ? x : [];
const s0 = v => String(v ?? '');
const MAX = 1000, JE = 10;
const LEER = 'Das lässt sich nicht rückgängig machen.';
const name = t => s0(t.anzeigename || t.name || ('Talent ' + t.id));
const kanaele = t => LI(t.kanaele).filter(k => k.status !== 'getrennt');
const zielPk = { seite: 'talents', parameter: { papierkorb: '1' } };
const blatt = (tab, n) => { const s = Math.max(1, Number((E.seiten || {})[tab]) || 1); return Math.min(s, Math.max(1, Math.ceil(n / JE))); };

return $('Testdaten kennzeichnen').all().map(it => {
  const j = it.json || {};
  const I = j.inhalt;
  if (!I || typeof I !== 'object' || !I.seite || W.ok !== true) return { json: j };
  const seite = I.seite;
  const verw = W.darf_verwalten === true, adm = W.darf_loeschen === true;
  const ar = LI(I.abschnitte).find(a => a && a.id === 'archiv');
  if (s0(P.papierkorb) === '1') {
    const bereich = s0(seite.titel) || 'Dashboard';
    seite.titel = 'Papierkorb';
    seite.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: bereich, ziel: { seite: 'talents' } }, { text: 'Papierkorb' }];
    seite.beschreibung = 'Talents im Papierkorb: Abrufe ruhen, Einladungslinks gelten nicht mehr. Zahlen, Beiträge und Notizen bleiben erhalten, bis du sie endgültig löschst.'
      + ' Die Löschfrist der Einstellungen gilt weiter.';
    delete seite.hauptaktion; delete seite.aktionen; delete seite.filter; delete seite.knoepfe; delete seite.formular; delete seite.speichern;
    const ab = [];
    if (ar) {
      ar.titel = 'Im Papierkorb'; ar.offen_standard = true;
      for (const b of LI(ar.inhalt)) {
        if (b.typ === 'filter') b.label = 'Papierkorb durchsuchen';
        if (b.typ !== 'tabelle') continue;
        b.titel = 'Im Papierkorb';
        for (const sp of LI(b.spalten)) if (sp.schluessel === 'seit') sp.titel = 'Im Papierkorb seit';
        b.leer = /Suche/.test(s0(b.leer)) ? 'Keine Talents im Papierkorb für diese Suche.' : 'Der Papierkorb ist leer.';
        for (const z of LI(b.zeilen)) {
          const c = (z.zellen || {}).aktion, tn = s0(((z.zellen || {}).name || {}).text);
          // Layout 7 (Plan 34, Prüfliste 8): beide Aktionen als Textaktionen in einer Reihe, „Wiederherstellen“ zuerst, wie in den Papierkörben von Kampagnen
          // und Reports (vorher „Endgültig löschen“ als Text der Zelle, darunter versetzt „Wiederherstellen“). Rückfrage und Fenster unverändert.
          if (c && typeof c === 'object' && c.aktion && c.aktion.aktion === 'tl_talent_reaktivieren') {
            const akt = [Object.assign({}, c.aktion, { text: 'Wiederherstellen',
              frage: '„' + tn + '“ wiederherstellen? Das Talent ist dann wieder aktiv. Für neue Verbindungen braucht es einen neuen Einladungslink.' })];
            if (/^loeschen-/.test(s0(c.fenster))) akt.push({ text: 'Endgültig löschen', fenster: s0(c.fenster) });
            z.zellen.aktion = { aktionen: akt };
          }
        }
      }
      ab.push(ar);
    }
    // Papierkorb leeren: genau die Talents der Suche (wie die Tabelle), höchstens 1000
    const aq = s0(P.aq).trim().toLowerCase().slice(0, 100);
    const pk = LI(W.talents).filter(t => t && t.status === 'archiviert' && (!aq || (name(t) + ' ' + (t.name || '') + ' ' + (t.kuenstlername || '') + ' ' + (t.email || '') + ' '
      + kanaele(t).map(k => k.extern_name || '').join(' ')).toLowerCase().includes(aq.replace(/^@/, ''))));
    const ids = pk.slice(0, MAX).map(t => s0(t.id)).filter(x => /^[0-9]{1,9}$/.test(x));
    const fenster = LI(I.fenster).filter(f => f && /^loeschen-/.test(s0(f.id)));
    for (const f of fenster) f.titel = s0(f.titel).replace(/ löschen$/, ' endgültig löschen');
    if (adm && ids.length) {
      seite.hauptaktion = { text: 'Papierkorb leeren', art: 'neben', fenster: 'papierkorb-leeren' };
      fenster.push({ id: 'papierkorb-leeren', art: 'dialog', titel: 'Papierkorb leeren', inhalt: [
        { typ: 'hinweis', ton: 'warn', text: (ids.length === 1 ? '„' + name(pk[0]) + '“ wird' : (ids.length === pk.length && !aq ? 'Alle ' : '') + ids.length + ' Talents'
            + (aq ? ' dieser Suche' : ' im Papierkorb') + (pk.length > MAX ? ' (die ersten 1000)' : '') + ' werden')
          + ' endgültig gelöscht, mit allen Zahlen, Beiträgen und Notizen. Dateien im Speicherort löscht Ally danach. ' + LEER },
        { typ: 'formular', id: 'papierkorb-leeren', aktion: 'tl_papierkorb_leeren', werte: { ids: ids.join(',') },
          felder: [{ typ: 'text', name: 'bestaetigung', label: 'Zur Bestätigung eingeben: löschen', pflicht: true, autocomplete: 'off' }],
          knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Papierkorb leeren' }] }] });
    }
    // KI-Texte ohne Talent im Papierkorb (Migration 130, talents_profil_pk_liste ohne Talent)
    const TX = PL && PL.ok === true ? LI(PL.eintraege) : [];
    if (TX.length) {
      const bl = blatt('texte-papierkorb', TX.length);
      ab.push({ id: 'texte-papierkorb', titel: 'Texte ohne Talent', zahl: String(TX.length), offen_standard: true, inhalt: [
        { typ: 'tabelle', id: 'texte-papierkorb', titel: 'Texte ohne Talent', spalten: [{ schluessel: 'titel', titel: 'Text' }, { schluessel: 'geloescht', titel: 'Gelöscht' }, { schluessel: 'aktion', titel: 'Aktion' }],
          zeilen: TX.slice((bl - 1) * JE, bl * JE).map(v => ({ zellen: { titel: s0(v.titel), geloescht: { text: s0(v.geloescht), neben: s0(v.geloescht_von) }, aktion: { aktionen: [
            { text: 'Wiederherstellen', aktion: 'tp_papierkorb_wiederherstellen', werte: { id: s0(v.id) }, frage: 'Text „' + s0(v.titel) + '“ wiederherstellen?' },
            { text: 'Endgültig löschen', aktion: 'tp_papierkorb_endgueltig', werte: { id: s0(v.id) }, frage: 'Text „' + s0(v.titel) + '“ endgültig löschen? ' + LEER }] } } })),
          seite: bl, je_seite: JE, gesamt: TX.length, leer: '' },
        { typ: 'aktion', text: 'Texte endgültig löschen', aktion: 'tp_papierkorb_leeren', werte: { ids: TX.slice(0, MAX).map(v => s0(v.id)).join(',') },
          frage: (TX.length === 1 ? 'Den Text' : 'Alle ' + Math.min(TX.length, MAX) + ' Texte') + ' ohne Talent im Papierkorb endgültig löschen? ' + LEER }] });
    }
    I.abschnitte = ab;
    I.fenster = fenster;
    delete I.ueberblick; delete I.bloecke;
    return { json: j };
  }
  // Liste: Archiv → Papierkorb (Knopf oben ohne Zähler)
  I.abschnitte = LI(I.abschnitte).filter(a => !(a && a.id === 'archiv'));
  I.fenster = LI(I.fenster).filter(f => !(f && /^loeschen-/.test(s0(f.id))));
  if (Array.isArray(seite.aktionen)) seite.aktionen = seite.aktionen.filter(a => !(a && a.text === 'Archiv'));
  seite.knoepfe = LI(seite.knoepfe).filter(k => !(k && k.text === 'Papierkorb')).concat([{ text: 'Papierkorb', ziel: zielPk }]);
  const U = I.ueberblick || {};
  for (const k of LI(U.kennzahlen)) if (typeof k.neben === 'string') k.neben = k.neben.replace(/ im Archiv$/, ' im Papierkorb');
  for (const ka of LI(U.karten)) for (const e of LI(ka.eintraege)) if (e && e.ziel_text === 'Archiv') { e.ziel = zielPk; e.ziel_text = 'Papierkorb'; }
  return { json: j };
});

// Papierkorb: Löschen umbenennen (ALLY 24 und 25, Migration 130, E13 „Löschen = Papierkorb“; Koordinator 24.10.2026).
// Ergänzt die Seite, ohne die Knoten davor zu ändern: Knöpfe „Löschen“ der Unterobjekte heißen „In den Papierkorb“ und fragen entsprechend nach
// (KI-Text tx_loeschen, Konzept-Ziel kz_ziel_loeschen, manueller Wert tm_wert_loeschen, Notiz tn_loeschen, Aufgabe kp_aufgabe_loeschen);
// Hinweise zu archivierten Talents heißen „im Papierkorb“. Die Datenbank legt die Einträge in den Papierkorb (talents_profil_pk_legen).
const FRAGE = {
  tx_loeschen: 'Diesen Text in den Papierkorb legen? Im Papierkorb kannst du ihn wiederherstellen.',
  kz_ziel_loeschen: 'Dieses Ziel in den Papierkorb legen? Im Papierkorb kannst du es wiederherstellen.',
  tm_wert_loeschen: 'Diesen Wert in den Papierkorb legen? Im Papierkorb kannst du ihn wiederherstellen.',
  tn_loeschen: 'Notiz in den Papierkorb legen? Im Papierkorb kannst du sie wiederherstellen.'
};
const TEXTE = {
  'Das Talent ist archiviert. Die Strategie lässt sich nur ansehen.': 'Das Talent liegt im Papierkorb. Die Strategie lässt sich nur ansehen.',
  'Für archivierte Talents lässt sich der Ally-Chat nicht einschalten.': 'Für Talents im Papierkorb lässt sich der Ally-Chat nicht einschalten.'
};
const geh = x => {
  if (Array.isArray(x)) { x.forEach(geh); return; }
  if (!x || typeof x !== 'object') return;
  if (typeof x.aktion === 'string' && (FRAGE[x.aktion] || x.aktion === 'kp_aufgabe_loeschen')) {
    if (x.text === 'Löschen') x.text = 'In den Papierkorb';
    x.frage = x.aktion === 'kp_aufgabe_loeschen'
      ? String(x.frage || 'Eintrag löschen?').replace(/ löschen\?$/, ' in den Papierkorb legen?') + ' Im Papierkorb kannst du den Eintrag wiederherstellen.'
      : FRAGE[x.aktion];
  }
  if (typeof x.text === 'string' && TEXTE[x.text]) x.text = TEXTE[x.text];
  for (const k of Object.keys(x)) geh(x[k]);
};
return $input.all().map(it => { const j = it.json || {}; geh(j.inhalt); return { json: j }; });

parameters.query:
-- Einladung-Versand laden (ALLY 24, Plan 57, Migration 192): Stand, Grenzen, sendefähige Postfächer und Vorschauen für das Fenster „Einladung für …“
-- je Talent (talent_einladung_fenster prüft Sitzung, Sichtbarkeit und Recht wie „Neuer Link“). Nur lesend. $1 Sitzung, $2 Talents (Komma-Liste, leer = nichts).
SELECT talent_einladung_fenster($1::text, $2::text) AS ev;

parameters.jsCode:
// Einladung per Mail (ALLY 24, Plan 57, Migration 192; Konzept Einladungsmail Teil 2, Entscheidungen Stefan 01.11.2026): ergänzt das vorhandene Fenster
// „Einladung für …“ um die drei Wege, ohne die Knoten davor zu ändern: „Als Entwurf ablegen“ (wie Korrespondenz › Mail-Entwurf anlegen), „Über den Absender für
// Systemnachrichten senden“ und „Über mein Postfach senden“ (eigene und freigeschaltete gemeinsame Postfächer mit eingerichtetem Versand, Standard-Postfach zuerst).
// Daten aus „Einladung-Versand laden“ (talent_einladung_fenster): Stand, Sperren und Grenzen, sendefähige Postfächer, Vorschauen der Mail; Rechte und Prüfung in der
// Datenbank (beim Senden noch einmal). Nur vorhandene Muster: Unterüberschrift mit i, graue Zeile für Stand und Sperren, Formulare mit Titel und i, Feld mailvorschau,
// Auswahl mit zeigen_wenn, Rückfrage (frage) mit benanntem Knopf. Gesendet wird über me_anlegen (ALLY 20 „Werkzeug-Felder“ → talents_mail_entwurf_anlegen mit versand).
const aus = $('Talents (Papierkorb)').all().map(x => x.json);
let EV = {};
try { EV = ($input.first().json || {}).ev || {}; } catch (e) { EV = {}; }
if (!EV || typeof EV !== 'object' || Array.isArray(EV)) EV = {};
const L = x => Array.isArray(x) ? x : [];
const s = v => String(v ?? '');
const P0 = (($('Start').first().json || {}).parameter) || {};
const TID = /^[0-9]{1,9}$/.test(s(P0.id)) ? s(P0.id) : '';
const opt = (w, t) => ({ wert: s(w), text: s(t) });
const pfText = p => s(p.adresse);   // nur die Adresse: am Handy ganz sichtbar (Prüfliste 16)
const ALT = 'Es wird nichts automatisch verschickt: Link oder Text kopieren und dem Talent schicken.';
const NEU = 'Link oder Text kopieren und dem Talent schicken oder unten per Mail senden. Ally verschickt nur, wenn du dort einen Weg wählst und bestätigst.';
const vorschau = (name, v, extra) => Object.assign({ typ: 'mailvorschau', name, label: 'Vorschau', von: s(v.von), an: s(v.an), betreff: s(v.betreff), html: s(v.html) }, extra || {});
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.fenster)) continue;
  for (const F of I.fenster) {
    const m = /^einladung(?:-([0-9]{1,9}))?$/.exec(s(F && F.id));
    if (!m || !Array.isArray(F.inhalt)) continue;
    const tid = m[1] || TID, V = EV[tid];
    if (!tid || !V || V.darf !== true) continue;
    for (const b of F.inhalt) if (b && b.typ === 'formular') for (const f of L(b.felder)) if (f && f.name === 'link') f.info = L(f.info).map(x => x === ALT ? NEU : x);
    const sfx = '-' + tid, an = s(V.an);
    const neu = [{ typ: 'unterueberschrift', text: 'Einladung per Mail',
      info: 'Ally schickt die Einladung im Corporate Design mit dem Knopf „Accounts verbinden“. Ob sie rausging, steht danach beim Talent unter Kommunikation › Korrespondenz.' }];
    if (V.letzter) neu.push({ typ: 'text', ton: 'grau', text: s(V.letzter) });
    const E = V.entwurf || {}, EP = L(E.postfaecher).filter(p => p && p.adresse);
    if (E.moeglich === true && EP.length) neu.push({ typ: 'formular', id: 'einladung-entwurf' + sfx, titel: 'Als Entwurf ablegen',
      info: 'Die Mail liegt danach im Entwurfsordner des gewählten Postfachs. Abschicken musst du sie selbst.', aktion: 'me_anlegen',
      werte: { talent_id: tid, art: 'einladung', versand: 'entwurf' },
      felder: [{ typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: s((EP.find(p => p.standard === true) || EP[0]).adresse), optionen: EP.map(p => opt(p.adresse, pfText(p))) }],
      knoepfe: [{ text: 'Entwurf ablegen', art: 'neben' }] });
    else if (E.moeglich === true) neu.push({ typ: 'text', ton: 'grau', text: 'Als Entwurf: kein Postfach mit eingeschalteten Mail-Entwürfen.' });
    if (V.sperre) neu.push({ typ: 'text', ton: 'grau', text: s(V.sperre) });
    else {
      const S = V.system || {};
      if (S.moeglich === true && S.vorschau) neu.push({ typ: 'formular', id: 'einladung-system' + sfx, titel: 'Über den Absender für Systemnachrichten senden',
        info: 'Ally schickt die Mail im Namen der Firma. Sie geht in etwa einer Minute raus.', aktion: 'me_anlegen',
        werte: { talent_id: tid, art: 'einladung', versand: 'system' }, felder: [vorschau('vorschau_system', S.vorschau)],
        frage: 'Einladung jetzt an ' + an + ' senden? Absender: ' + s(S.vorschau.von) + '. Die Mail geht in etwa einer Minute raus.',
        knoepfe: [{ text: 'Jetzt senden', art: 'neben' }] });
      else neu.push({ typ: 'text', ton: 'grau', text: s(S.grund || 'Kein Absender für Systemnachrichten eingerichtet (Einstellungen › Postfächer, nur Admin).') });
      const PF = L((V.postfach || {}).postfaecher).filter(p => p && p.adresse && p.vorschau);
      if (PF.length) {
        const felder = PF.length > 1 ? [{ typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: s(PF[0].adresse), optionen: PF.map(p => opt(p.adresse, pfText(p))) }] : [];
        PF.forEach((p, i) => felder.push(vorschau('vorschau_' + i, p.vorschau, PF.length > 1 ? { zeigen_wenn: { feld: 'postfach', werte: [s(p.adresse)] } } : {})));
        neu.push({ typ: 'formular', id: 'einladung-postfach' + sfx, titel: 'Über mein Postfach senden',
          info: 'Ally schickt die Mail sofort über das Postfach, mit deinem Namen und deiner Signatur.', aktion: 'me_anlegen',
          werte: Object.assign({ talent_id: tid, art: 'einladung', versand: 'postfach' }, PF.length === 1 ? { postfach: s(PF[0].adresse) } : {}), felder,
          frage: PF.length === 1 ? 'Einladung jetzt über ' + s(PF[0].adresse) + ' an ' + an + ' senden?' : 'Einladung jetzt über das gewählte Postfach an ' + an + ' senden?',
          knoepfe: [{ text: 'Über mein Postfach senden', art: 'neben' }] });
      } else neu.push({ typ: 'text', ton: 'grau', text: s((V.postfach || {}).grund || 'Für dich ist kein Postfach mit Versand eingerichtet (Einstellungen › Meine Postfächer, Abschnitt „Zugang und Versand“, „Versand erlauben“).') });
    }
    // nach „Im Mailprogramm öffnen“ (sonst nach dem ersten Formular), vor den Textaktionen („Zum Talent“, „Neuer Link“)
    let pos = -1;
    F.inhalt.forEach((b, i) => { if (b && b.mailto) pos = i; });
    if (pos < 0) pos = F.inhalt.findIndex(b => b && b.typ === 'formular');
    F.inhalt.splice(pos + 1, 0, ...neu);
  }
}
return aus.map(json => ({ json }));
